const SEED_DATA = [{"id": "c1", "name": "Po výpadku", "entries": [{"id": "e1", "text": "PO VÝPADKU", "images": [], "videos": []}, {"id": "e2", "text": "Pec 3 - zpětná čerpadla nahodit, zkontrolovat i na peci 1 a 2", "images": [], "videos": []}, {"id": "e3", "text": "V čerpačce pozapínat opět čerpadla tak jak byla (jde poznat podle otevřených ventilů)", "images": [], "videos": []}, {"id": "e4", "text": "Zapnout pece opět - na peci 3 zapnout jističe uvnitř, na 1 a 2 ventilátory vypnout - pak zapnout hlavní a opět zapnout ventilátory, hořáky zapnout - hlavní, přepnout na 1 hořák a zapnout počkat až dosáhne 2,2,mA - zapnout zbývající, přesvědčit se přes okénka", "images": [], "videos": []}, {"id": "e5", "text": "Kotelna", "images": [], "videos": []}, {"id": "e6", "text": "Chyby na panelu kotle -zkusit vymazat na panelu - SIGNAL,ZRUSIT a na displeji ACK, pokud nelze (je porucha hořáku) ->  vypnout hořák až na pozici odblokovat ->  vymazat chyby na displeji ACK -> zapnout hořák na I. Stupeň  -> počkat na min. 4bar na manometru  -> může se zapnout na II. Stupeň", "images": [], "videos": []}, {"id": "e7", "text": "Chyby většinou NEJNIŽŠÍ STAV VODY - kontrola vodoznaku - dopouští kotelník, PORUCHA HOŘÁKU - vypnout hořák a znovu zapnout (postup výše)", "images": [], "videos": []}, {"id": "e8", "text": "Někdy je potřeba natáhnout 24 HOD. KONTROLU", "images": ["Po_výpadku_1.jpg", "Po_výpadku_2.jpg", "Po_výpadku_3.jpg", "Po_výpadku_4.jpg", "Po_výpadku_5.jpg"], "videos": []}, {"id": "e9", "text": "Pokud přetéká voda v jímce -> odčerpání do kanálu", "images": [], "videos": []}, {"id": "e10", "text": "Aby se nehrnula voda z výroby může se vypnout zpětná čerpadla na peci 1 a 2 - přetečou přepadem do kanálu", "images": [], "videos": []}]}, {"id": "c2", "name": "Fin", "entries": [{"id": "e11", "text": "Heslo válce: 12017", "images": [], "videos": []}, {"id": "e12", "text": "Výměna nože", "images": [], "videos": []}, {"id": "e13", "text": "nové nože, klíč na povolení, léra do kanálku, papír", "images": [], "videos": []}, {"id": "e14", "text": "Zvednou scroll, uvolnit", "images": [], "videos": []}, {"id": "e15", "text": "Povolit spodní nůž - celé lůžko (Fin 5 sundat i kryt kanálku + upevnit zpět část lůžka po výměně spodního nože)", "images": [], "videos": []}, {"id": "e16", "text": "Vyměnit spodní nůž výškově na léru (ne výše), usadit tak  aby se opřel o horní nůž (ten je dole)", "images": [], "videos": []}, {"id": "e17", "text": "Horní - odjistit, pozor na klínek, zapřít zezadu, povolit klíčem", "images": [], "videos": []}, {"id": "e18", "text": "Horní nesmí být ohlý od spodního (tzn.doprava). Ke spodnímu (doleva) být může, ale hůř stříhá", "images": [], "videos": []}, {"id": "e19", "text": "NOŽE- pokud možno stejně potahované", "images": [], "videos": []}, {"id": "e20", "text": "Palec asi 1,5 mm ve finu - další vlna za palcem na hraně spodního nože (nasimulovat nahuštění jako od scrollu)", "images": [], "videos": []}, {"id": "e21", "text": "Pokud je sjetá strana vodícího kanálu bude se namotávat na nůž (fin má vůli do stran)", "images": [], "videos": []}, {"id": "e22", "text": "Když se namotává na nůž = víc natlačit k sobě", "images": [], "videos": []}, {"id": "e23", "text": "Scroll - lze nastavit výšku (hloubku zapuštění), posun do stran", "images": [], "videos": []}, {"id": "e24", "text": "Nůž v manuálu moc na volno (volná ložiska) = dotáhnout kontramatku z druhé strany", "images": [], "videos": []}, {"id": "e25", "text": "Špatný střih - formovací válce, nabírání, scroll, nastavení válečků - č.1 tak aby byl fin před nimi hladký (na Finu 5 - tak rychle než se začne rozhazovat)→", "images": [], "videos": []}, {"id": "e26", "text": "→č.2 tak aby držela délka", "images": [], "videos": []}, {"id": "e27", "text": "Postup při výměně nožů:", "images": [], "videos": []}, {"id": "e28", "text": "Je potřeba nejprve zkontrolovat zda nože stříhají.", "images": [], "videos": []}, {"id": "e29", "text": "Proto ověřte zda dochází ke střihu pomocí papírové pásky příp.  pásky finu.", "images": [], "videos": []}, {"id": "e30", "text": "Pokud nedojde k přestřižení papírové pásky je nutné oba nože vyměnit.", "images": [], "videos": []}, {"id": "e31", "text": "Při výměně nožů je třeba počítat s tím,že se nože brousí a ubývá materiál nožů. Tím se mění pozice střihu a je nutné také pozici upravit.", "images": [], "videos": []}, {"id": "e32", "text": "Pokud dojde k přestřižení papírové pásky nože se měnit nemusí, ale je potřeba změnit hloubku plíšku „arestoru“ nebo změnit pozici střihu.", "images": [], "videos": []}, {"id": "e33", "text": "Pozice se upravuje tak, že se povolí 2ks šroubů M8 na hrazdě pro arestor a nastaví se pomocí mikrometrických šroubů nová pozice.Pak se 2ks šroubů M8 dotáhnou.", "images": [], "videos": []}, {"id": "e34", "text": "Správná pozice střihu – místo střihu viz.  na obr. vlevo se pohybuje cca  0 - 0,5mm před břitem spodního nože.", "images": [], "videos": []}, {"id": "e35", "text": "Hloubka „plíšku“arestoru je v rozmezí cca 1 – 2,5 mm na obr.  vlevo ( vše je závislé na tloušťce a šířce materiálu i rychlosti stroje), pozice „plíšku“ je znázorněna na obr. vpravo.", "images": [], "videos": []}, {"id": "e36", "text": "Nafázovaní nože", "images": [], "videos": []}, {"id": "e37", "text": "když nůž už stříhá, musí arestor už jít nahorů (nesmí setrvávat dlouho v dolní pozici)", "images": [], "videos": []}, {"id": "e38", "text": "když fin zastavuje a nic nepíše jen svítí červeně - tlak v nádobě oleje  (ne průtok) nebo otevřený odvzdušňovací ventil", "images": [], "videos": []}, {"id": "e39", "text": "Válce", "images": [], "videos": []}, {"id": "e40", "text": "při zavádění pásky když nenajede pod shlukovací rovně, ale udělá oblouk = shlukovací jsou špatně nastavené", "images": [], "videos": []}, {"id": "e41", "text": "Shlukovací válce - nabírání (černý válec) - povolit dva šrouby (ten naproti nepovolovat), musí zabírat na přední stranu spodku vlny", "images": [], "videos": []}, {"id": "e42", "text": "vymezení vůle - spodní je půlený, lze nastavit vymezení", "images": [], "videos": []}, {"id": "e43", "text": "horní - vrchol zubu musí být naproti středu spodních (mezi dva zuby) cca 1 mm vysoko, lze nastavit horním kolíkem (červy jako na formovacích)", "images": [], "videos": []}, {"id": "e44", "text": "Formovací válce - spodní na vymezení vůle, horní - upravit Jodon", "images": [], "videos": []}, {"id": "e45", "text": "Fin - zahlý = nastavit/vyměnit válečky - nastavit na dotek + 3 dílky dotáhnout", "images": [], "videos": []}, {"id": "e46", "text": "Fin - vytrhávají se části okének = špatně vystředěné válce, můžou být špatně sestavené disky (prohozené),pokud vše OK - nadzvednout válce - vypodložit", "images": [], "videos": []}, {"id": "e47", "text": "Jodon", "images": [], "videos": []}, {"id": "e48", "text": "začátek finu jak najíždí ze stroje", "images": [], "videos": []}, {"id": "e49", "text": "kontrola poškození - kraje musí být OK a nesmí to být vidět v jádře", "images": [], "videos": []}, {"id": "e50", "text": "roztáhnout na cca 90°", "images": [], "videos": []}, {"id": "e51", "text": "ikona LAC 2000", "images": [], "videos": []}, {"id": "e52", "text": "rozstříhnout a ohnout, PRAVÁ horní okénka otevřená (je přes ně vidět)", "images": [], "videos": []}, {"id": "e53", "text": "vložit do zakladačky dle modelu", "images": [], "videos": []}, {"id": "e54", "text": "fin 16 mm šířka x 7 mm výška = 16x0,07 (ve volbě materiálu) - zakladačka 16x7", "images": [], "videos": []}, {"id": "e55", "text": "naohýbat do neúplného čtverce po 90° po šesti/ osmi vrcholech, rozstříhat na délce - z každého 4", "images": [], "videos": []}, {"id": "e56", "text": "Počítač →Select→Select forming roll→Zvolit číslo formovacích válců - OK", "images": [], "videos": []}, {"id": "e57", "text": "→Enter info→Enter operator responses→Vyplnit tabulku - OK", "images": [], "videos": []}, {"id": "e58", "text": "→Run test - vložit zakladačku - vždy se měří 12 vzorků, po 12 ks - okénko x", "images": [], "videos": []}, {"id": "e59", "text": "→Print→Print report→Yes→Yes→Prewiev", "images": [], "videos": []}, {"id": "e60", "text": "→File→Print→Preferences→Landspaces (tisk na šířku)→Print", "images": [], "videos": []}, {"id": "e61", "text": "Po odměření - Aux funcions→Shut down comp", "images": [], "videos": []}, {"id": "e62", "text": "Výsledek od -2 do 2 je OK, louver kolem 29", "images": [], "videos": []}, {"id": "e63", "text": "Chci do mínusu (výsledek je v plusu), jdu dolů ->povolit 3 velké imbusy->pravý červ povolit->levý dotáhnout", "images": [], "videos": []}, {"id": "e64", "text": "do plusu jdu nahorů→povolit 3 velké imbusy→levý červ povolit→prový dotáhnu", "images": [], "videos": []}, {"id": "e65", "text": "pro válce lepší když Jodon vyjde +1 až +1,5", "images": [], "videos": []}, {"id": "e66", "text": "Výsledek R= max 3 - pokud je vyšší můžou být prohozené disky, špičky nejsou stejně zarovnané nebo málo zapuštěné", "images": [], "videos": []}, {"id": "e67", "text": "fin - pokud je výška mimo hranici: zpětný tah na stroji dát výše než 0, a na budíku více než 1MPa - 3MPa", "images": [], "videos": []}, {"id": "e68", "text": "5Q0 válce zpětného tahu", "images": [], "videos": []}, {"id": "e69", "text": "na světlých válcích se vrací cívka zpět (velký zpětný tah)", "images": [], "videos": []}, {"id": "e70", "text": "pokud se válce netočí - nastavit přes vzduchový regulátor přítlak poté požadovanou výšku ladit přes displej", "images": [], "videos": []}, {"id": "e71", "text": "Fin 3", "images": [], "videos": []}, {"id": "e72", "text": "zpětný tah na 54 - pokud je moc vysoký = válce se vrací zpět dozadu", "images": [], "videos": []}, {"id": "e73", "text": "Fin 4", "images": [], "videos": []}, {"id": "e74", "text": "nejde vzduch na paletovači (i když je vše puštěno)→vypnout fin→vypnout Enable→zapnout fin + Enable", "images": [], "videos": []}, {"id": "e75", "text": "VÁLCE", "images": [], "videos": []}, {"id": "e76", "text": "když se nebudou rozebírat: vyfoukat otřít, NESTŘÍKAT ANI CLEANEREM", "images": [], "videos": []}, {"id": "e77", "text": "TOP - spodní válce", "images": [], "videos": []}, {"id": "e78", "text": "BOTTOM - horní válce", "images": [], "videos": []}, {"id": "e79", "text": "povolit horní část (obě točit stejně)", "images": [], "videos": []}, {"id": "e80", "text": "sundat ozubená kola (červy) - šroubovákem ze dvou stran", "images": [], "videos": []}, {"id": "e81", "text": "vytáhnout na hřídeli ven (přidržovat si kraje - otáčí se)→sundat část k předku šrouby válců jsou směrem k operátorovi(tam kde je kolo pro otáčení)→", "images": [], "videos": []}, {"id": "e82", "text": "→omýt nad sudem→hned sundat válce (vybouchat o dřevo) a povolit je ve sklíčidle (tam je potom také dotáhnout)→", "images": [], "videos": []}, {"id": "e83", "text": "pokud se bude sundavat i zadní část - změřit vzdálenost k ozubenému kolu, svěrné pouzdro - vyšroubovat 4x šrouby a zašroubovat do dvou volných otvorů = povolí", "images": [], "videos": []}, {"id": "e84", "text": "rozebrat válce - nezamíchat disky (jdou zaměnit různé sekce - zrcadlově převrácením mezi horními a dolními válci), povolovat a dotahovat ve sklíčidle - křížem", "images": [], "videos": []}, {"id": "e85", "text": "šrouby ze strany válců jsou směrem k předku (s kolem pro otáčení)", "images": [], "videos": []}, {"id": "e86", "text": "promazat ložiska v bočnici pro uložení hřídele (vmačkat dovnitř) bílou vazelínu", "images": [], "videos": []}, {"id": "e87", "text": "při sestavování musí jít nasadit zlehka, lehce stříknout WDčkem (pokud se kousnou tak vyndat a znovu), pokud je vůle - vymezit ji (vypodložit pero nebo dát nové nebo novou hřídel)", "images": [], "videos": []}, {"id": "e88", "text": "opatrně vkládat do rámu", "images": [], "videos": []}, {"id": "e89", "text": "správně nasadit vymezovací podložky na spodní hřídeli, na konec hřídele - máznout hnědou vazelínou pro nasazení ozubených kol", "images": [], "videos": []}, {"id": "e90", "text": "vyčištěné uložení i podložky→nasadit ozubená kola - nadoraz", "images": [], "videos": []}, {"id": "e91", "text": "spodní válce - vystředit kanálek", "images": [], "videos": []}, {"id": "e92", "text": "horní válce - vystředit podle spodních, lérou z boků", "images": [], "videos": []}, {"id": "e93", "text": "když se dávají dohromady - povolit červíky na kolíku ozubeného kola (Jodon), dotáhnout prsty zpět a truchu povolit, na cit→povolit 3x imbus a pomalu dolů (aby si sedly samy", "images": [], "videos": []}, {"id": "e94", "text": "na ozubených kolech podle značek (2x tečka spodní, 1x tečka horní) nastavit pozici→vložit odpovídající fin mezi válce a pomalu dotahovat shora", "images": [], "videos": []}, {"id": "e95", "text": "vyzkoušet Jodon→po nasazení vždy na corefinech udělat nabírání", "images": [], "videos": []}, {"id": "e96", "text": "Rozebrání válců", "images": [], "videos": []}, {"id": "e97", "text": "předek je se šrouby, všechny disky (kromě dodaných z protějších válců) musí jít popsáním nahoru směrem k operátorovi", "images": [], "videos": []}, {"id": "e98", "text": "před rozebráním válců povolit 4 x červíky zezadu (brání povolení imbusů)→pak povolit imbusy ve sklíčidle→posadit si je na dřevěné a pěnové podložení a vyklepnout duralem 2x lícované imbusy", "images": [], "videos": []}, {"id": "e99", "text": "při sestavování lícované rovnou naklepnout místo fixačních (na Fordu, 5Q0), na 8W0, TBC se sestavují rovnou na lícované", "images": [], "videos": []}, {"id": "e100", "text": "DISKY", "images": [], "videos": []}, {"id": "e101", "text": "T - top (dolní)", "images": [], "videos": []}, {"id": "e102", "text": "B - bottom (horní)", "images": [], "videos": []}, {"id": "e103", "text": "otočené protože je směr jízdy z prava do leva (na rozdíl od Anglie)", "images": [], "videos": []}, {"id": "e104", "text": "krajní disky jsou slabší než středové a úplně středové (8K0, FORD)", "images": [], "videos": []}, {"id": "e105", "text": "střed válců po sestavení: na vodorovné ploše musí vycházet do Λ, na svislé do V", "images": [], "videos": []}, {"id": "e106", "text": "krajní plošky na vodorovné: Δ trojúhelníky na obou koncích, na svislé nejsou", "images": [], "videos": []}, {"id": "e107", "text": "středové plošky na vodorovné:  Δ trojúhelníky stejně velké, sklon směr do středu z obou stran", "images": [], "videos": []}, {"id": "e108", "text": "středové plošky na svislé:  Δ trojúhelníky stejně velké (menší než na vodorovné), sklon směr od středu", "images": [], "videos": []}, {"id": "e109", "text": "nesmí se zaměnit!!!", "images": ["Fin_7.jpg", "Fin_8.jpg"], "videos": []}, {"id": "e110", "text": "Válce k dispozici", "images": [], "videos": []}, {"id": "e111", "text": "1x sestavené 8W0 ve stojanu", "images": [], "videos": []}, {"id": "e112", "text": "1x sestavené Ford ve stojanu", "images": [], "videos": []}, {"id": "e113", "text": "2x 5Q0", "images": [], "videos": []}, {"id": "e114", "text": "Nové disky po sestavení můžou být vyšší a trhat tak pásku - po úpravě Jodonu OK", "images": [], "videos": []}, {"id": "e115", "text": "finy z válců - zahlé dolů = moc v mínusu (v platech do leva)", "images": [], "videos": []}, {"id": "e116", "text": "- zahlé nahorů = moc v plusu (v platech do prava)", "images": [], "videos": []}, {"id": "e117", "text": "Přechod na jinou pásku", "images": [], "videos": []}, {"id": "e118", "text": "silnější páska - pokud je louver dostatečně nízko - nemusí se vypodkládat", "images": [], "videos": []}, {"id": "e119", "text": "snížit válce = zvýší se louver", "images": [], "videos": []}, {"id": "e120", "text": "vypodložit válce = sníží se louver", "images": [], "videos": []}, {"id": "e121", "text": "VŽDY DÁVAT PÁSKU MEZI VÁLCE KDYŽ SE DÁVAJÍ K SOBĚ  i když se dávají jen podložky", "images": [], "videos": []}, {"id": "e122", "text": "raději dávat podložky vyšší a potom postupně snižovat", "images": ["Fin_9.jpg"], "videos": []}]}, {"id": "c3", "name": "Řezačka", "entries": [{"id": "e123", "text": "Heslo: 168911", "images": [], "videos": []}, {"id": "e124", "text": "Nejvyšší heslo: 1342487", "images": [], "videos": []}, {"id": "e125", "text": "Širší okraje trubek/skosené – povolit válečky", "images": [], "videos": []}, {"id": "e126", "text": "Křivé trubky – válečky naproti sobě jen aby se točily, ostatní rovnají trubku (na posledním - aby se točill)", "images": [], "videos": []}, {"id": "e127", "text": "Dancing - nebrzdila cívka, povytažený konektor ze serva (malý = brzda), velký = přívod", "images": [], "videos": []}, {"id": "e128", "text": "Kamera - RESET chyba barvy - Resetovat v AUTOMATU!!!", "images": [], "videos": []}, {"id": "e129", "text": "Přestavba", "images": [], "videos": []}, {"id": "e130", "text": "Nářadí nahoru, při výměně rovnacích válců pozor na prostřední nohu řezačky", "images": [], "videos": []}, {"id": "e131", "text": "sundat kartáč", "images": [], "videos": []}, {"id": "e132", "text": "povolit válečky (plastové bílé),v kalibraci vyndat bloky - prostříknout uvnitř WD", "images": [], "videos": []}, {"id": "e133", "text": "boční kalibrační bloky - za půlkou patří dolu", "images": [], "videos": []}, {"id": "e134", "text": "spodní kalibrace (8W0, TBC, TGN) podložky 0,04 mm", "images": [], "videos": []}, {"id": "e135", "text": "vyměnit oba díly při vstupu k noži", "images": [], "videos": []}, {"id": "e136", "text": "otočit plasty za noži (jiné trubky)", "images": [], "videos": []}, {"id": "e137", "text": "montáž plastu ke šnekům (8W0, TBC, TGN)", "images": [], "videos": []}, {"id": "e138", "text": "12 mm tooling nevyndavá se léra za kartáčováním", "images": [], "videos": []}, {"id": "e139", "text": "16 mm tooling na EJ7H se vyndá, na 5Q0 musí být - zadní stranou nehýbat = 0", "images": [], "videos": []}, {"id": "e140", "text": "5Q0", "images": [], "videos": []}, {"id": "e141", "text": "válečky za kartáčem - dát léru", "images": [], "videos": []}, {"id": "e142", "text": "Ford", "images": [], "videos": []}, {"id": "e143", "text": "kartáč nasadit", "images": [], "videos": []}, {"id": "e144", "text": "válečky za kartáčem -vyndat léru", "images": [], "videos": []}, {"id": "e145", "text": "Řezačka 4", "images": [], "videos": []}, {"id": "e146", "text": "FORD - 1066/1050/1016/1009//120/92/131/141", "images": [], "videos": []}, {"id": "e147", "text": "8W0,TBC,TGN - 9996,4/9996,4/9996,2/9996,5//101/120/105/134", "images": [], "videos": []}, {"id": "e148", "text": "5Q0 - 1034/1032/998/980//120/92/129/140", "images": [], "videos": []}, {"id": "e149", "text": "Délka trubky při dojezdu cívky:", "images": ["Řezačka_10.jpg", "Řezačka_11.jpg"], "videos": []}, {"id": "e150", "text": "ŘEZAČKA 3", "images": [], "videos": []}, {"id": "e151", "text": "00/0 | 99/8 | 00/0 | 99/4", "images": [], "videos": []}, {"id": "e152", "text": "155 | 129 | 148 | 147", "images": [], "videos": []}, {"id": "e153", "text": "4.11. | 00/0 | 99/8 | 00/0 | 99/4", "images": [], "videos": []}, {"id": "e154", "text": "149 | 105 | 145 | 147", "images": [], "videos": []}, {"id": "e155", "text": "2016-09-19 00:00:00 | 00/1 | 00/0 | 00/2 | 00/1", "images": [], "videos": []}, {"id": "e156", "text": "5Q0 krátká | 150 | 126 | 141 | 146", "images": [], "videos": []}, {"id": "e157", "text": "2016-11-06 00:00:00 | 00/0 | 00/0 | 00/1 | 00/0", "images": [], "videos": []}, {"id": "e158", "text": "152 | 121 | 147 | 146", "images": [], "videos": []}, {"id": "e159", "text": "ŘEZAČKA 4", "images": [], "videos": []}, {"id": "e160", "text": "5Q0 | 1034 | 1032 | 1016 | 980", "images": [], "videos": []}, {"id": "e161", "text": "120 | 92 | 129 | 140", "images": [], "videos": []}, {"id": "e162", "text": "2016-11-12 00:00:00 | 1034 | 1031 | 976 | 967", "images": [], "videos": []}, {"id": "e163", "text": "120 | 92 | 129 | 141", "images": [], "videos": []}, {"id": "e164", "text": "8W0 | 964 | 964 | 960 | 960", "images": [], "videos": []}, {"id": "e165", "text": "113 | 120 | 105 | 129", "images": [], "videos": []}, {"id": "e166", "text": "964 | 964 | 961 | 965", "images": [], "videos": []}, {"id": "e167", "text": "107 | 99 | 115 | 127", "images": [], "videos": []}, {"id": "e168", "text": "FORD | 1069 | 1070 | 1050 | 1009", "images": [], "videos": []}, {"id": "e169", "text": "117 | 92 | 129 | 146", "images": [], "videos": []}, {"id": "e170", "text": "1069 | 1071 | 1033 | 1041", "images": [], "videos": []}, {"id": "e171", "text": "125 | 92 | 129 | 146", "images": [], "videos": []}, {"id": "e172", "text": "12.11. | 1063 | 1070 | 1031 | 985", "images": [], "videos": []}, {"id": "e173", "text": "132 | 103 | 130 | 140", "images": [], "videos": []}, {"id": "e174", "text": "1066 | 1050 | 1016 | 1009", "images": [], "videos": []}, {"id": "e175", "text": "120 | 92 | 131 | 141", "images": [], "videos": []}, {"id": "e176", "text": "Válce nastavení", "images": [], "videos": []}, {"id": "e177", "text": "druhý od cívky - nadzvednout (pamatovat o kolik) aby se nedotýkal trubky", "images": [], "videos": []}, {"id": "e178", "text": "první od cívky - nastavit aby bral polovinu a více ze surové tloušťky (1,56 mm = 1,53 mm po projetí pod válcem)", "images": [], "videos": []}, {"id": "e179", "text": "Výměna hřídele šnek - sundat ozubené kolo - za ním klínek a kroužek, jinak se vyrazí ložiska!", "images": [], "videos": []}, {"id": "e180", "text": "Bourání trubek", "images": [], "videos": []}, {"id": "e181", "text": "nevychází odhoz trubky do šneků - fázování (schovat šneky víc k rampě) a rampu snížit", "images": [], "videos": []}, {"id": "e182", "text": "Kartáčování", "images": [], "videos": []}, {"id": "e183", "text": "rozebrat - sundat kartáče - vyčistit nad sudem", "images": [], "videos": []}, {"id": "e184", "text": "část napružinách rozebrat - povolit úplně 4 šrouby a zatočit zpět na 2 závity a vytahovat kus který drží (jinak vše vyletí ven)", "images": [], "videos": []}, {"id": "e185", "text": "ložiska - WD promazat aby opravdu jezdila", "images": [], "videos": []}, {"id": "e186", "text": "kartáče na staré hřídele - vrtákem 8,1", "images": [], "videos": []}, {"id": "e187", "text": "Vystředění kalibrace", "images": [], "videos": []}, {"id": "e188", "text": "ve skladu, Různé - Háčko + kolíčky", "images": [], "videos": []}, {"id": "e189", "text": "z horní kalibrace sundat válečky, povolit 4 a 4 šrouby - vytočit nahoru - vsunout Háčko, dotáhnout", "images": [], "videos": []}, {"id": "e190", "text": "povolit na hřídeli boční kalibrace (vzadu) 4 šrouby = uvolněno, s boční kalibrací hnout nad díry - zakolíkovat", "images": [], "videos": []}, {"id": "e191", "text": "vše dotáhnout", "images": [], "videos": []}, {"id": "e192", "text": "Nastavení kalibrace na displeji", "images": [], "videos": []}, {"id": "e193", "text": "Konec formovací původ návrat pozice oprava - výchozí pozice kalibrace např. z -3000 na -8500", "images": [], "videos": []}, {"id": "e194", "text": "Nastavení řezu na displeji", "images": [], "videos": []}, {"id": "e195", "text": "Řezací původ návrat pozice oprava - výchozí pozice řezu např. z 20000 na 3000", "images": [], "videos": []}]}, {"id": "c4", "name": "Corefin", "entries": [{"id": "e196", "text": "DÉLKA FINU – válečky č. 3, povolit = prodloužit, pokud je fin stále dlouhý a nic nepomáhá = změnit rychlosti na válečkách č. 2 a č. 3", "images": [], "videos": []}, {"id": "e197", "text": "HRBATÝ FIN – přítlak na válečkách č. 1, nebo zpomalit", "images": [], "videos": []}, {"id": "e198", "text": "ŠIKMÝ FIN – válečky č. 1: a) šikmý směrem k válcům/shlukování finu před válečky = zrychlit", "images": [], "videos": []}, {"id": "e199", "text": "b) šikmý od válců/hrbatý/mezery před válečky = zpomalit", "images": [], "videos": []}, {"id": "e200", "text": "-fin nereaguje na změnu rychlosti -> lišta nad kanálkem (za shlukovacími válci) možná brání finu v pohybu", "images": [], "videos": []}, {"id": "e201", "text": "na finu 6 - podložky pod kanálem u zhlukovacích valců 2x3mm podložky za F.V. a 1x3mm za S.V.", "images": [], "videos": []}, {"id": "e202", "text": "- jiné nastavení rychlostí na 2. a 3.", "images": [], "videos": []}, {"id": "e203", "text": "Nabírání na CF6-povolit i červy na hřídeli ozubených kol", "images": [], "videos": []}, {"id": "e204", "text": "po rozjezdu krátký fin, potom se protáhne - příliš velká rychlost na pack up č.1", "images": [], "videos": []}, {"id": "e205", "text": "nakloněný fin od válců - podložit spodní shlukovačky aby byly víc do kanálku", "images": [], "videos": []}, {"id": "e206", "text": "Nabírání na CF8 - CF11 - povolit na spojce k ozubenému kolu a nastavit", "images": [], "videos": []}, {"id": "e207", "text": "RYCHLOSTI na válečkách č. 2 a č. 3 – 2,400 a 2,600- na 6/2,500 a 2,700 na 7. Snížení pomáhá při vysokém finu, zpětný tah je nižší", "images": [], "videos": []}, {"id": "e208", "text": "ŠPATNÝ STŘIH – na Finu: Model No. Selection -> Šnek pro přísun materiálu – změnit", "images": [], "videos": []}, {"id": "e209", "text": "Nebo na Finu -> Maintenance – Zpoždění přísunu materiálu", "images": [], "videos": []}, {"id": "e210", "text": "PROSTŘÍHLÝ FIN – musí být prostříhý formovacími válci uprostřed, jinak není rovný", "images": [], "videos": []}, {"id": "e211", "text": "DEFORMACE KONCE FINŮ – lišta na konci cesty finu musí být ok + kostka", "images": [], "videos": []}, {"id": "e212", "text": "DUMMY PLATE – vzdálenost od drážky v bubnu 71 mm, pokud nevychází na drážku v pásu = posunout pás", "images": [], "videos": []}, {"id": "e213", "text": "POSUNUTÍ PÁSU -> levá hrana kanálu zároveň s levou hranou zubu pásu, když se vloží trubka (v max. vůli k levé straně zubu) je kousek za levou hranou kanálu (blíž k operátorovi)", "images": [], "videos": []}, {"id": "e214", "text": "TRANSFER – přední část, 300 mm od Dummy plate, pokud nejde posunout tak přes manuál – PRAVÁ DESKA", "images": [], "videos": []}, {"id": "e215", "text": "Nulová pozice výtahu 75mm od podkladu k začátku silonu (na CF8 je to 80mm)", "images": [], "videos": []}, {"id": "e216", "text": "153,156 – když horní praporky bourají do sideplate = nastavit ručně (povolit šroubky)", "images": [], "videos": []}, {"id": "e217", "text": "152 – spadlý poslední fin (většinou) = kontrola – rovný dummy plate, správná pozice dummy plate a transferu", "images": [], "videos": []}, {"id": "e218", "text": "157 – nedojelo víko na kraji", "images": [], "videos": []}, {"id": "e219", "text": "73 - víko není v VP", "images": [], "videos": []}, {"id": "e220", "text": "horní deska při pohybu dolů nejezdila plynule nebo se v pohybu i vracela - problém byl ve snímači na pneuválci víka prvního finu, přiznával slabě", "images": [], "videos": []}, {"id": "e221", "text": "NASTAVENÍ HŘEBENŮ CF6,7 – při zavřených hřebenech: od operátora 29mm- 6,5mm- 6,5mm- 6,5mm- 6mm", "images": ["Corefin_17.jpg"], "videos": []}, {"id": "e222", "text": "Po kompresi", "images": [], "videos": []}, {"id": "e223", "text": "PROMÁČKLÉ KRAJNÍ FINY – změna vybouchávání ČÍSLO JÁDRA POZICE – snížit hodnoty asi o 1 mm (utáhnout)", "images": [], "videos": []}, {"id": "e224", "text": "NAHUŠTĚNÉ FINY – změna SUB SUB POZICE+KONCE ŽEBRA- ÚPRAVA POZICE 3 – zvýšit hodnoty (povolit)", "images": [], "videos": []}, {"id": "e225", "text": "NEVYBOUCHANÉ JÁDRO – zvýšit ČÍSLO POZICE (povolit)", "images": [], "videos": []}, {"id": "e226", "text": "-do středového kusu kompresní tyče byl dán delší šroub a spodní deska nevybouchávala", "images": [], "videos": []}, {"id": "e227", "text": "65 – hřebeny bourají do trubek = nastavit hřebeny/pokud přítlačná lišta ohýbá finy = nastavit ji asi 1 mm nad okraj vodící lišty", "images": [], "videos": []}, {"id": "e228", "text": "KŘIVĚ ZAKLÁDÁ HEADER – srovnat výšku najíždění (RD - dorazy na zakladačce, H1 - 10 šroubů)/ Model No. Selection -> Vkládání -> Posun (vlevo, vpravo)", "images": [], "videos": []}, {"id": "e229", "text": "Kontrola najíždění trubek a sideplat do headerů – Tabule s žebry – dolů -> Okruh-> Pozice korekce", "images": [], "videos": []}, {"id": "e230", "text": "-zkontrolovat jestli jsou headery kolmo k tabuli -> pokud NE = hýbat s dorazy", "images": [], "videos": []}, {"id": "e231", "text": "pokud ANO = vložit trubku do horní a dolní části headeru -> výškově seřídit (10 šroubů)", "images": [], "videos": []}, {"id": "e232", "text": "-kontrola desky proti tlumičům – vymačkané díry = rameno nedojede do polohy", "images": [], "videos": []}, {"id": "e233", "text": "115 - na CF8, posunout pasy dopředu nevychází k bubnu", "images": [], "videos": []}, {"id": "e234", "text": "PŘETÁČENÍ TRUBKY – snižuju počet kusů", "images": [], "videos": []}, {"id": "e235", "text": "ZASEKÁVÁNÍ TRUBKY – zvyšuji počet kusů", "images": [], "videos": []}, {"id": "e236", "text": "ZASEKÁVÁNÍ DLOUHÉ TRUBKY – rolničky pro posun byly příliš blízko k sobě (dovnitř zásobníku)", "images": [], "videos": []}, {"id": "e237", "text": "ZASEKÁVÁNÍ KRÁTKÉ TRUBKY – vymezovací kameny nastavení", "images": [], "videos": []}, {"id": "e238", "text": "Nastavení DUMMY plate CF8 - CF11", "images": [], "videos": []}, {"id": "e239", "text": "1. Home position -> vložím metr (od bubnu/domku) -> DUMMY dolů -> zjistím kam a o kolik posunout", "images": [], "videos": []}, {"id": "e240", "text": "2. Dummy plate nahoru -> Maintenence - záložka dummy - posunout na 0 (protože je v  Home posunut o 1mm dopředu) -> posunout kam potřebuji -> Origin", "images": [], "videos": []}, {"id": "e241", "text": "3. Do Home -> dummy plate dolů - vychází mezi zuby/je na požadované vzdálenosti (metrem) =OK", "images": [], "videos": []}, {"id": "e242", "text": "Nastavení transferu", "images": [], "videos": []}, {"id": "e243", "text": "1. Home position -> kontrola podle 1mm/podle metru (dummy plate dolů) - zjistím kam a o kolik posunout", "images": [], "videos": []}, {"id": "e244", "text": "2. V Maintenence - záložka transfer -> posunout na 0 (protože je v Home posunut o 30 mm) -> posunout kam potřebuji -> Origin", "images": [], "videos": []}, {"id": "e245", "text": "3. Do Home - kontola -> přeměřit", "images": [], "videos": []}, {"id": "e246", "text": "Nulová hodnota CF 6 – 629mm, CF 7 – 669mm, CF - 8 -11 - zpětná pozice", "images": [], "videos": []}, {"id": "e247", "text": "143 – nevysouvá naskládaná platíčka", "images": [], "videos": []}, {"id": "e248", "text": "202 – nakládání dlouhé trubky -> sebrat plata -> najet nakladačem do výchozí polohy, Request long tube by měl být na ZAPNUTO", "images": [], "videos": []}, {"id": "e249", "text": "206 - nakládání krátké trubky - Request short tube", "images": [], "videos": []}, {"id": "e250", "text": "112 – pokud je nízká hodnota na průletovém čidle – MODE + SET – zmáčknout obě najednou 2x", "images": [], "videos": []}, {"id": "e251", "text": "112 - pokud je v pořádku najíždění finu mezi trubky a fin občas najede mimo (nad finy vlevo) = zkontrolovat vzduch jestli fin nevytlačuje z dráhy (ubrat nebo srovnat naklonění vzduchu)", "images": ["Corefin_12.jpg"], "videos": []}, {"id": "e252", "text": "Snímač na CF8", "images": [], "videos": []}, {"id": "e253", "text": "Vložit fin -> zmáčknout SET na 3s", "images": [], "videos": []}, {"id": "e254", "text": "Vyndat fin -> zmáčknout SET na 3s", "images": [], "videos": []}, {"id": "e255", "text": "Pro trubku", "images": [], "videos": []}, {"id": "e256", "text": "Vložit trubku do nejbližšího slotu -> zmáčknout SET na 3s", "images": [], "videos": []}, {"id": "e257", "text": "Vložit trubku do druhého nejbližšího (raději o trochu blíž)-> zmáčknout SET na 3s", "images": [], "videos": []}, {"id": "e258", "text": "Přetrhává se páska - odlehčit dancig = přidat protizávaží", "images": [], "videos": []}, {"id": "e259", "text": "Deska mezi krajními částmi kompresní tabule má být na volno- jinak se kříží", "images": [], "videos": []}, {"id": "e260", "text": "Deformace finu ze scrollu = vzduch na ofuk nože má být naplno", "images": [], "videos": []}, {"id": "e261", "text": "Fin 8 – vytahuju první fin = vzduch na ofuk konce finu spadlý", "images": [], "videos": []}, {"id": "e262", "text": "Ohnutí první trubky = srovnat buben", "images": [], "videos": []}, {"id": "e263", "text": "Corefin 8, 9", "images": [], "videos": []}, {"id": "e264", "text": "ROBO cylinder - brzdy = srovnat", "images": [], "videos": []}, {"id": "e265", "text": "chyba 65 na CB9 - v Maintenence - OSA 8-1 (Header Insertion L - parametr Šneková dráha (Fin pos. Dec pos.) z 67 mm na 40 mm", "images": [], "videos": []}, {"id": "e266", "text": "Corefin 6,7 scroll nafázování", "images": ["Corefin_13.jpg"], "videos": []}, {"id": "e267", "text": "Levý je na pevno s hřídelkou - nastaví se jako první (povytáhne se a otočí), tak aby palec ukazoval šikmo dolů", "images": [], "videos": []}, {"id": "e268", "text": "Pravý je kluzný - nastaví se podle levého, aby byly náběhy souběžně", "images": [], "videos": []}, {"id": "e269", "text": "vyzkoušet si se zavedeným finem - nesmí jedna strana být napřed než druhá jinak nastavit kluzný znovu", "images": [], "videos": []}, {"id": "e270", "text": "scrolly proti sobě musí být:", "images": [], "videos": []}, {"id": "e271", "text": "Vytahuje trubku - pasy napnout (nevychází na mezeru, ale na hranu)", "images": [], "videos": []}, {"id": "e272", "text": "Výměna nože", "images": [], "videos": []}, {"id": "e273", "text": "oba najeto stejně (horní buď otočit nebo také vyměnit)", "images": [], "videos": []}, {"id": "e274", "text": "vystřeďovač pro upevnění středového palce", "images": [], "videos": []}, {"id": "e275", "text": "Stohovací pasy", "images": [], "videos": []}, {"id": "e276", "text": "po chybě se posune stohovací pas = moc naplý", "images": [], "videos": []}, {"id": "e277", "text": "horní dopnutí = dopnutí k liště", "images": [], "videos": []}, {"id": "e278", "text": "vodorovné = pro napnutí pasu", "images": [], "videos": []}, {"id": "e279", "text": "CF 9 padá druhý fin - volný stohovací, dopnout velkou rolnou", "images": ["Corefin_15.jpg"], "videos": []}, {"id": "e280", "text": "CF 10 a CF 11", "images": [], "videos": []}, {"id": "e281", "text": "srovnání vyhazovačů", "images": ["Corefin_16.jpg"], "videos": []}, {"id": "e282", "text": "Přestavba nových finů", "images": [], "videos": []}, {"id": "e283", "text": "- vyndat Y za shlukovacími válci = uvolnit 3x imbus", "images": [], "videos": []}, {"id": "e284", "text": "- vytáhnout konektory + vzduch, na displeji odepnout pohon formovacích a shlukovacích válců = BACKWARD", "images": [], "videos": []}, {"id": "e285", "text": "- uvolnit FV + SV →vyměnit→ připojit přes displej→zapojit konektor + vzduchy", "images": [], "videos": []}, {"id": "e286", "text": "- vyměnit dráhy, vyměnit scrolly (uvonit scroll přes displej - SCROLL OFF) klíč 23 + imbus, nastavit výšku horního nože na doraz dráhy na druhý model léra", "images": [], "videos": []}, {"id": "e287", "text": "Snímače na transferu - indukční pár ze strany, snímá plech - nahrazuje bezpečnostní závoru, stejné na ramenech pro headery atd.", "images": [], "videos": []}, {"id": "e288", "text": "CF7 - dopravník je stále spuštěný (při chybě na core), musí se vypnout fin a znovu zapnout - světlovod za nožem má stále přiznávat / na CF6 nemá přiznávat", "images": [], "videos": []}, {"id": "e289", "text": "Kamera na trubky CF 12, 14, 15", "images": [], "videos": []}, {"id": "e290", "text": "trubka se švem - OK, posledních  aspoň 5 a na nějakém modelu 6 trubek švem dovnitř", "images": [], "videos": []}, {"id": "e291", "text": "vyfotit trubku se švem, vybrat nej obrázek - pro aktualní potvrzení Trigger - pokud nebere zesvětlit/ztmavit rozsah", "images": [], "videos": []}, {"id": "e292", "text": "12, 13, 14, 15", "images": [], "videos": []}, {"id": "e293", "text": "Nejde způvodnit komprese - přes řemenici ji dostat blíž k bubnu na snímač (ten u operátora) a poslat domů. Musí mít vyšší aktuální hodnotu, jinak nepojede na snímač k bubnu.", "images": [], "videos": []}, {"id": "e294", "text": "Pokud má nízkou hodnotu - přes manuál přijet dopředu, potom odpojit řemen/servo a dotlačit ručně jednotku k bubnu - připojit servo a znovu dopředu. 2x 900mm", "images": ["Corefin_18.jpg"], "videos": []}, {"id": "e295", "text": "Jodon - formovací válce", "images": [], "videos": []}, {"id": "e296", "text": "Do plusu vždy po směru jízdy, jen na nových když jsou bottom nahoře tak proti směru = +", "images": [], "videos": []}]}, {"id": "c5", "name": "Roboti", "entries": [{"id": "e297", "text": "HESLO Flexi Alík: 007", "images": [], "videos": []}, {"id": "e298", "text": "HESLO Analogy: 2029", "images": [], "videos": []}, {"id": "e299", "text": "Vibrační zařízení – A = lišta, B = vibrák", "images": [], "videos": []}, {"id": "e300", "text": "Protáčí se header RD – snížení tlaku na sekeře, upravit čidlo na sekeře pro sepnutí", "images": [], "videos": []}, {"id": "e301", "text": "Zakladačka nedovírá/neotvírá – šroubky na upevnění headeru zkontrolovat, pokud nepomůže kontrola čidla pod plechem, utáhnout šroubek na pístu pod zakladačkou", "images": [], "videos": []}, {"id": "e302", "text": "Komora s flangí bourá – nesedí hodnoty na digitálním panelu = upravit pozici na pístu na kterém je komora upevněna", "images": [], "videos": []}, {"id": "e303", "text": "Přeskakuje sváry - ve výchozí pozici dát na flexi PP na main", "images": [], "videos": []}, {"id": "e304", "text": "Analogy - úprava když moc vyhazuje", "images": [], "videos": []}, {"id": "e305", "text": "flange  - pohybovat hodnoty", "images": [], "videos": []}, {"id": "e306", "text": "Ničí snímač RD víček - zkontrolovat měřák podtlaku. Vyzkoušet zapnout ejektor bez víčka např. -20 a s víčkem např. -50. Tak nastavit minimální hodnotu na -30", "images": [], "videos": []}, {"id": "e307", "text": "Úprava sváry", "images": [], "videos": []}, {"id": "e308", "text": "vypnout svářečku", "images": [], "videos": []}, {"id": "e309", "text": "podle modelu najít číslo programu např. 5WA = program 14", "images": [], "videos": []}, {"id": "e310", "text": "na flexi Editor programu- Odladit - Welding č. programu (např. 14)", "images": [], "videos": []}, {"id": "e311", "text": "vybrat v postupu programu odpovídající krok", "images": [], "videos": []}, {"id": "e312", "text": "podle stolu STN1 nebo STN2", "images": [], "videos": []}, {"id": "e313", "text": "První pohyb - Move L - PP na kurzor (vedle řádku musí být šipka)→ a jet (motory + step - vedle play) - procházet sváry", "images": [], "videos": []}, {"id": "e314", "text": "V programu se pohybovat přes řádky (vybrat takto řádek) - PP na kurzor", "images": [], "videos": []}, {"id": "e315", "text": "pak najet na první svár (vybrat řádek) Move L - začátek sváru ArcStart - označit hvězdičku * pak Odladit→Zobrazit parametry - parametry v mm - osy - X - dopředu, dozadu Y - vlevo, vpravo (vlevo sloty RD headeru)", "images": [], "videos": []}, {"id": "e316", "text": "Nebo nastavit pozici robota kde chci aby byl a pak označit hvězdičku →Upravit vybrané→znovu  označit hvězdičku a OK- uloží aktuální pozici", "images": [], "videos": []}, {"id": "e317", "text": "Nebo přes souřadnice - hvězdička a pak Odladit →ABC...", "images": [], "videos": []}, {"id": "e318", "text": "vlevo je PLUS, pravo je MÍNUS", "images": [], "videos": []}, {"id": "e319", "text": "konec sváru ArcEnd opět přes hvězdu upravit parametry", "images": [], "videos": []}, {"id": "e320", "text": "Pak Rutiny - smazat pro druhý stůl a zkopírovat z prvního stolu a přejmenovat na původní jméno", "images": [], "videos": []}, {"id": "e321", "text": "pro vylepšení svárů - na panelu pro svářečku - najít parametry - zvýšit hodnoty v Ampérech a Voltech", "images": [], "videos": []}, {"id": "e322", "text": "přestane svařovat →Možnosti obnovení → Obnovit", "images": [], "videos": []}, {"id": "e323", "text": "osička pro lůžko na RD přepážky - flexou uříznout 10 mm pak zabrousit na 7 mm a zalepit na stroji", "images": [], "videos": []}, {"id": "e324", "text": "Nepodává drát nebo jede zpět - hlídáno páčkou v banánu. Je příliš nahoře", "images": [], "videos": []}]}, {"id": "c6", "name": "Core", "entries": [{"id": "e325", "text": "Core", "images": [], "videos": []}, {"id": "e326", "text": "Kontrola", "images": [], "videos": []}, {"id": "e327", "text": "1. Zkontolovat stlačení podle modeláku (kompresi)", "images": [], "videos": []}, {"id": "e328", "text": "2. Hřebeny - porovnat se základní deskou na které jsou upevněny (přesah nahoře i dole musí být na stejno)", "images": [], "videos": []}, {"id": "e329", "text": "3. Tyče - mezery od hřebenů musí být stejné jak nahoře tak i dole (aby nebylo kosé jádro)", "images": [], "videos": []}, {"id": "e330", "text": "4. Sklopná ramena - malá vůle pro trubku musí být", "images": [], "videos": []}, {"id": "e331", "text": "5. Nájezdy + výškové nastavení pro headery (v manuálu po odepnutí indexu znovu sepnout horní čelist)", "images": [], "videos": []}, {"id": "e332", "text": "nájezdy - stejné mezery od středové desky - VŠUDE (LEVÁ i PRAVÁ strana nahoře i dole v uchycení headeru)", "images": [], "videos": []}, {"id": "e333", "text": "nájezdy nastavovat na dva sloty od středu svařence (H2) k závoře", "images": [], "videos": []}, {"id": "e334", "text": "výškově - PŘIDRŽET při nastavování, ze strany povolit matku a nastavit imbusem(uniká vzduch při vstupu do závory), index zastrčit", "images": [], "videos": []}, {"id": "e335", "text": "zašroubovat = širší jádro, posun o hranu je asi o 0,1 mm", "images": [], "videos": []}, {"id": "e336", "text": "kontrola po přestavbách jestli sedí stůl na dorazech (pak se může pořád hýbat šířka jádra)", "images": [], "videos": []}, {"id": "e337", "text": "PŘI KONTROLOVÁNÍ - VÝŠKOVĚ - DOTAHOVAT ŠROUBY - hne se to", "images": [], "videos": []}, {"id": "e338", "text": "Nastavení náklonu headeru - doraz pod dolní čelistí (dál od závory)", "images": [], "videos": []}, {"id": "e339", "text": "Sklopné ramena - stejně rychlé dojíždění, stejná vzdálenost od trubky cca 0,2 mm, když už nejdou snížit na dorazu dají se snížit na konstrukci po vyndání kolíku", "images": [], "videos": []}, {"id": "e340", "text": "Nabouraná trubka - může být už od tyče deformovaná (pokud nemá vůli)", "images": [], "videos": []}, {"id": "e341", "text": "Střed stolu - pokud padají finy, mohou se zasekávat o zuby uprostřed = zvedlá středová deska (zanesení fluxem, dorazy pod deskou) -", "images": [], "videos": []}, {"id": "e342", "text": "při demontáži pozor na díly mezi zuby jsou na volno", "images": [], "videos": []}, {"id": "e343", "text": "nedojíždí stlačení jádra - kontrola hřebenů, jestli dojíždí na snímače", "images": [], "videos": []}, {"id": "e344", "text": "pokud nejde seřídit nájezd (nedrží), nastavit přední část, dotáhnout a pak zadní část", "images": [], "videos": []}, {"id": "e345", "text": "pokud trubky bourají uprostřed nahoře = nastavit sklopná ramena na dorazech aby byla mezera na stole jen pro trubku", "images": [], "videos": []}, {"id": "e346", "text": "core 21 a 22 - v automatu nechat složit→pak do závory (před najetím headerů)→vyskočí tabulka - Reset poruchy - nepotvrzovat, ale obejít přes Menu→", "images": [], "videos": []}, {"id": "e347", "text": "→Poruchy→Reset - pak teprve do Ručně a popojet si s nájezdy", "images": [], "videos": []}, {"id": "e348", "text": "core22 - když se jede FORD musí být zaplý v programu 1G0", "images": [], "videos": []}, {"id": "e349", "text": "na core se musí zvolit správný model - tří headrový nebo dvou headerový", "images": [], "videos": []}, {"id": "e350", "text": "když se nesklápí ramena v Ručním lze kouknout které nejede, jde přepnout na sklápění jen jednoho L/P", "images": [], "videos": []}, {"id": "e351", "text": "nastavení času sklápění ramen - 0,3 s (desetiny, pokud dlouho čeká může být přenastaveno!)", "images": [], "videos": []}, {"id": "e352", "text": "Model 470", "images": [], "videos": []}, {"id": "e353", "text": "při manipulaci v core jádro odsunout - sideplate se vkládá pod lištu - při vyjetí by se ohlo", "images": [], "videos": []}, {"id": "e354", "text": "po přestavbě kabel od zakladačky headerů schovat za šrouby - může dojít k přestřihnutí", "images": [], "videos": []}, {"id": "e355", "text": "vzduchy pro hřebeny - pod hřebeny - aby vyjížděly stejně", "images": [], "videos": []}, {"id": "e356", "text": "zakladačky pro headery - na 3 trubky od sředové desky", "images": [], "videos": []}, {"id": "e357", "text": "tyče - tak aby neprošla léra (může se dát jedna strana úplně k hřebenům, jako na 0 a podle sestavení upravit)", "images": [], "videos": []}, {"id": "e358", "text": "pokud je krátká trubka OK mezi tyčemi, ale dlouhá se nevejde = vypodložit spoj na tyči", "images": [], "videos": []}, {"id": "e359", "text": "nízké/vysoké jádro - podložky pod stlačení", "images": [], "videos": []}, {"id": "e360", "text": "Volné finy po sestavení", "images": [], "videos": []}, {"id": "e361", "text": "něco zapadlé mezi hřebeny", "images": [], "videos": []}, {"id": "e362", "text": "rychle se stlačují hřebeny", "images": [], "videos": []}, {"id": "e363", "text": "headery najíždí nakoso", "images": [], "videos": []}]}, {"id": "c7", "name": "Banding", "entries": [{"id": "e364", "text": "Heslo: 1", "images": [], "videos": []}, {"id": "e365", "text": "Banding 32- není vyboucháno a mačká sideplate, 22 mm je podle modelového listu", "images": [], "videos": []}, {"id": "e366", "text": "Nový banding 11 a 12 (americký) - horní deska posuv dopředu a vzad - nad deskou je nastavování", "images": [], "videos": []}, {"id": "e367", "text": "chyba horní desky - vahadlo na pístu, vyčistit a nastavit", "images": [], "videos": []}, {"id": "e368", "text": "Chyba na závoře - problikává F a 5 - závora na výměnu", "images": [], "videos": []}, {"id": "e369", "text": "Starý bending", "images": [], "videos": []}, {"id": "e370", "text": "Zapnout vzduchy, nahodit rozvaděč", "images": [], "videos": []}, {"id": "e371", "text": "Start - jede", "images": [], "videos": []}, {"id": "e372", "text": "při čištění snímačů - vypnout (mohl by dostat signál pro zdviž a pokračovat). Kontrola spodních snímačů, vidí (svítí) stále, až když je portál před tak zhasne", "images": [], "videos": []}, {"id": "e373", "text": "stop tlačítka", "images": [], "videos": []}, {"id": "e374", "text": "frekvence - pro rychlosti odpovídající počtu kusů", "images": [], "videos": []}, {"id": "e375", "text": "pomalu jezdí horní deska - šktící ventily na obou koncích nastavit", "images": [], "videos": []}, {"id": "e376", "text": "Pro přístup do ovládání -> F4 a potom F6 - Motory (pozor jezdí na dvě strany)popsány na dvířkách rozvaděče uvnitř, výtahy - vstup a výstup", "images": [], "videos": []}]}, {"id": "c8", "name": "Helium", "entries": [{"id": "e377", "text": "GVA (vysokotlak)→GVL (vypuštění ze sběrnice)→GVW (evakuace, Tlak v kondenzátoru)→GVH (helium)→GVR (recyklace helia, Tlak v komoře)→GVN (nízkotlak - pro lepší sundání jigu)", "images": [], "videos": []}, {"id": "e378", "text": "Postup: Vysokotlak (50bar) →Vypustí + Evakuuje komoru + Evakuuje kondenzátor→Před test helium→Hlavní test helium (35bar)→", "images": [], "videos": []}, {"id": "e379", "text": "→Recyklace + Vyrovná se tlak v komoře + v kondenzátoru→Nízkotlak (1bar a méně) - aby se sundaly jigy snáze", "images": [], "videos": []}, {"id": "e380", "text": "4x ukazatele - Tlak v komoře, 1x ukazatel - Tlak v kondenzátoru", "images": [], "videos": []}, {"id": "e381", "text": "pokud je zaplá Kalibrace - je mimo vysokotlak - chladiče procházejí, je to omezeno jen na 5 min. pak se vypne", "images": [], "videos": []}, {"id": "e382", "text": "Zjistit, která komora má problém: zaslepit ->koukat na digitál kam stoupá/klesá tlak a podle hodnoty před chybou určit", "images": [], "videos": []}, {"id": "e383", "text": "Před chybou do mínusu - recyklace/evakuace SAJE - nezavírá se ventil", "images": [], "videos": []}, {"id": "e384", "text": "Před chybou do plusu FOUKÁ až na 50bar = vysokotlak GVA, 35bar = helium GVH, 1bar = nízký tlak GVN", "images": [], "videos": []}, {"id": "e385", "text": "Chyba na vysokotlak - někde uniká tlak (většinou přes GVL vypouštěcí ventil, který se otvírá/zavírá jako poslední. Nemusí se zavřít při posledním chladiči) =výměna relátek na GVL, pokud nepomůže tak rozebrat", "images": [], "videos": []}, {"id": "e386", "text": "jaký tlak vstoupil musí vystoupit = pokud na manometru klesá - někde se ztrácí (GVR, GVW, GVL) nebo roste - někde připouští (GVH, GVN)", "images": [], "videos": []}, {"id": "e387", "text": "horší se koncentrace = SAJE - recyklace GVR", "images": [], "videos": []}, {"id": "e388", "text": "problém GVW (evakuace komor) - neevakuuje se žádná komora, kontrola/výměna na všech komorách", "images": [], "videos": []}, {"id": "e389", "text": "problém GVR(evakuace kondenzátoru)", "images": [], "videos": []}, {"id": "e390", "text": "FOUKÁ = GVA, GVH, GVN", "images": [], "videos": []}, {"id": "e391", "text": "pozorovat měřák na komoře (co má zrovna napouštět a jak hodně) - pokud jde:", "images": [], "videos": []}, {"id": "e392", "text": "NAHORU - hledat u vysokotlaku, heliu, nízkotlaku", "images": [], "videos": []}, {"id": "e393", "text": "DOLŮ - evakuace, recyklace", "images": [], "videos": []}, {"id": "e394", "text": "AVV - vyrovnání tlaku v komorách", "images": [], "videos": []}, {"id": "e395", "text": "Při Kalibraci neprochází, až na podruhé - při nečinnosti komory jde tlak na budíku nahoru = tlačí se tam GVA nebo GVH, GVN (pro -GVN příliš vysoká hodnota)", "images": [], "videos": []}, {"id": "e396", "text": "vysokotlak - zastavit, vypustit přes GVL→pokud jde stále nahoru - tak to vysokotlak nebude", "images": [], "videos": []}, {"id": "e397", "text": "helium - zavřít tlakové lahve, zavřít ventil koncentrace, otevřít ventil vypuštění  (popsáno u ventilu odfouknout helium ventil 6)", "images": [], "videos": []}, {"id": "e398", "text": "povolovat přívodní hadičky jako kdyby byly pod tlakem", "images": [], "videos": []}, {"id": "e399", "text": "Jen jedna komora má problém a vše chodí OK (tlak neklesá, nestoupá) - přiložit prst jestli nesaje nebo nefouká→dát chladič jestli projde→nenapustil helium (GVA - ok), jen do 25bar = neseplo relé - výměna", "images": [], "videos": []}, {"id": "e400", "text": "Výměna GVR - při výrobě - přidržet prstem hadičku aby nesála vzduch - horší se koncentrace", "images": [], "videos": []}, {"id": "e401", "text": "Prochází na podruhé - vyndat relé GVN (může být zbytek helia v trubkách a fouká ho zpět do komory)", "images": [], "videos": []}, {"id": "e402", "text": "Zůstává tlak v jádře po testu VT (červená) - sundat z tlumiče na výfuku sítko", "images": [], "videos": []}, {"id": "e403", "text": "Neprochází na hélium - otřít dveře komory, vyčistit filtr uvnitř komory zespodu - odšroubovat, může být špatné pozadí = zapnout ventilátory", "images": [], "videos": []}, {"id": "e404", "text": "Pokud nemůže vyevakuovat jádro = může foukat vysokotlak přes jiné ventily nebo také může foukat přes ventil jiné komory - vylučovací metodou:", "images": [], "videos": []}, {"id": "e405", "text": "Snímač tlaku nad komorou, sonda poranění Ulvac WP-01 - po výměně evakuace OK", "images": [], "videos": []}, {"id": "e406", "text": "Když přes komory: Přepnu na komoru která má problém →k tomu pustit jinou komoru se záslepkou → přiložit prst - když začne foukat tak je to ona (postupně odsledovat všechny 3)", "images": [], "videos": []}, {"id": "e407", "text": "Když přes ventily: vyloučit nízkotlaký →zavřít nízkotlak, odpustit tlak →napustit vysokotlak (přes ovládací panel - GVA) - pokud roste více jak 1bar na monometru u médií = nespíná nízkotlaký ventil", "images": [], "videos": []}, {"id": "e408", "text": "vyloučit heliový ventil → vyšroubovat ventil helium (He1 - ten co jme dělali s Mírou), odpustit tlak helium na sběrnici přes výpušťák (opět zavřít) →napustit vysokotlakem a pokud roste tlak na monometru u médií = nezavírá heliový ventil", "images": ["Helium_24.jpg", "Helium_25.jpg"], "videos": []}, {"id": "e409", "text": "Pokud chci Auto start nebo Auto stop musí být nejdříve přepnuto na Auto", "images": [], "videos": []}, {"id": "e410", "text": "TSV - nad komorou k heliotu", "images": [], "videos": []}, {"id": "e411", "text": "ISV - před heliotem", "images": ["Helium_28.jpg"], "videos": []}, {"id": "e412", "text": "4. Helium - chyba tlaku helia (nemá helium) bílá nádoba u kompresoru vypíná při -50, pak nemá z čeho přisát  →zavřený přívod od lahve/lahev", "images": [], "videos": []}, {"id": "e413", "text": "pokud je vše OK a stále chyba tlaku - kompresor nestíhá natlačit - může se snížit hodnota z -50 na např. -40 (dočasné, do výměny kompresoru)", "images": [], "videos": []}, {"id": "e414", "text": "kompresor může i přisávat vzduch = chyba koncentrace→He DENSITY LOW ALARM na jednotce recyklace", "images": [], "videos": []}, {"id": "e415", "text": "Přepnout do IND→ podržet 5s He GAS CHANGE (trvá než se obnoví helium)", "images": ["Helium_42.jpg"], "videos": []}, {"id": "e416", "text": "4. Helium - neprochází na helium - kouknout ma sítko", "images": [], "videos": []}, {"id": "e417", "text": "pokud na budíku vedle ovládacího panelu ručička se nevrací dostatečně rychle - ucpané sítko uvnitř ventilu", "images": [], "videos": []}, {"id": "e418", "text": "ručička na budíku by se měla pohybovat svižně (předtest + test) - pokud ne, může být zanesené sítko ve ventilu (za budíkem)", "images": [], "videos": []}, {"id": "e419", "text": "Vyčistit sítko - zavřít přívody od kompresoru k ventilu, upustit helium přes potrubí ke komorám (vedle rozvaděče) - povolit převlečné matky", "images": [], "videos": []}, {"id": "e420", "text": "- vyndat ventil - rozebrat vpředu, odpojit přívod + odvod, ze strany přívodu je filtr (sítko) - vyndat a vyčistit", "images": [], "videos": []}, {"id": "e421", "text": "1. Vypnout si kompresor - skříň nad ovládáním recyklace", "images": [], "videos": []}, {"id": "e422", "text": "2. Vypnout hlavním recyklaci", "images": [], "videos": []}, {"id": "e423", "text": "3. a 4. Uzavřít ventily od a k kompresoru", "images": [], "videos": []}, {"id": "e424", "text": "5. Natrhnout ventil - na manometru klesne tlak (kolem 40bar)", "images": [], "videos": []}, {"id": "e425", "text": "6. Zavřít ventil = vyšroubovat kličku, povolit matku", "images": [], "videos": []}, {"id": "e426", "text": "7. Odšroubovat 2x převlečné matky", "images": [], "videos": []}, {"id": "e427", "text": "8. Vyndat ventil - odšroubovat L-ko na vstupu a vyčistit sítko", "images": [], "videos": []}, {"id": "e428", "text": "9. Nasadit zpět - našroubovat kličku na ventil - 13 celých otáček/27 půl otáček", "images": ["Helium_35.jpg", "Helium_36.jpg", "Helium_37.jpg", "Helium_38.jpg", "Helium_39.jpg", "Helium_40.jpg", "Helium_41.jpg"], "videos": []}, {"id": "e429", "text": "Dveře - nejdou zavřít (chyba Zkušební ventily a také nesvítí Automat - není ve VP) tak odpustit sběrnici na všech komorách", "images": [], "videos": []}, {"id": "e430", "text": "Dveře - zkušební ventily - normálně za provozu snímač vypnutý, při nastavování snímačů zapnout aby se dveře nezavřeli", "images": [], "videos": []}, {"id": "e431", "text": "Nešli zavřít dveře ani přes manuál - ve ventilu byl vzduch a neměl kam jít. Odpojení ventilu elektricky (aby nedostával signál), zkusit přepnout na ventilu. Pokud nejde odpojit hadičku aby se vypustil vzduch", "images": [], "videos": []}, {"id": "e432", "text": "Pojistky ELM - pojistky pro ventily - jednopólové, může být sepnutýjeden ventil -relátko (zjistit jaký = ten ventil který bude teplý)  → vyměnit relé", "images": [], "videos": []}, {"id": "e433", "text": "Relátka na heliu 3,4 po straně rozvaděče (jsou zapojena paralelně s těmi uprostřed rozvaděče)", "images": [], "videos": []}, {"id": "e434", "text": "Stop čerpadla - na pauzu, můžou být otevřené dveře", "images": [], "videos": []}, {"id": "e435", "text": "Automatický stop - vypínání  (vypne se vše)", "images": [], "videos": []}, {"id": "e436", "text": "He 1 - 4 ukončení se záslepkami, přepnout do ručně, zavřít všechny dveře pak přepnout do Automaticky a Automatický stop", "images": [], "videos": []}, {"id": "e437", "text": "pokud je vypínání bloknuté (špatně ukončené) - Ručně+Automaticky podržet na déle než 5s, pokud když se dá Automatický start a nezasvítí Připraveno je třeba v Ručním odfouknout tlak v potrubí GVL (stává se když se nechá v komoře kondentátor nebo záslepky)", "images": [], "videos": []}, {"id": "e438", "text": "v Ručním přepínat komoru po komoře a v každé odfouknout přes GVL, pokud ani to nepomůže zkusit postupně vyevakuovat jinak natvrdo vypnout ačekat než naběhne heliot", "images": [], "videos": []}, {"id": "e439", "text": "He 5 ukončení se záslepkami - Automaticky vypnout - můžou být vzadu spadlé dveře ze snímače= dveře přepnout do ručního a zpět = otevřou se vzadu - zavřít a znovu Vypnout", "images": [], "videos": []}, {"id": "e440", "text": "Ručně", "images": [], "videos": []}, {"id": "e441", "text": "pokud nejde hned do Ručně tak podržet Ručně + Auto na více než 5s", "images": [], "videos": []}, {"id": "e442", "text": "Přepínání komor - lze ovládat jednotlivé ventily", "images": [], "videos": []}, {"id": "e443", "text": "Reset - reset chyby, pokud jde", "images": [], "videos": []}, {"id": "e444", "text": "Média musí být zaplá: helium - páčka oteřená + otevřené lahve", "images": [], "videos": []}, {"id": "e445", "text": "Chyba koncentrace - upustit koncentraci, nechat napustit→ nový test→Reset chyby", "images": [], "videos": []}, {"id": "e446", "text": "nebyl otevřený ventil před měřením vzorku koncentrace", "images": [], "videos": []}, {"id": "e447", "text": "5. Helium - pod nádrží - vypouštěcí ventil", "images": [], "videos": []}, {"id": "e448", "text": "Při výměně ventilů", "images": [], "videos": []}, {"id": "e449", "text": "Vypnout - Ručně→min. Vypnout čerpadla/raději vše (Automatický stop)→odtlakovat média→", "images": [], "videos": []}, {"id": "e450", "text": "vysokotlak - zavřít ventil→odpustit tlak v trubkách", "images": [], "videos": []}, {"id": "e451", "text": "nízkotlak- zavřít ventily→odpustit tlak v trubkách", "images": [], "videos": []}, {"id": "e452", "text": "helium - zavřít lahev)→odpustit recyklaci na:", "images": [], "videos": []}, {"id": "e453", "text": "1. Helium - dole u menší nádoby otevřít výpušťák", "images": [], "videos": []}, {"id": "e454", "text": "2. Helium - vypouští se nad skříní s kompresory (páka rovnoběžně s trubkou)", "images": [], "videos": []}, {"id": "e455", "text": "3. Helium - vypouští se uvnitř skříně s kompresory, popsáno. Displej hodnota Nádoba 3", "images": [], "videos": []}, {"id": "e456", "text": "vypouští asi 15 min., zpět napouští 30 min.", "images": [], "videos": []}, {"id": "e457", "text": "pokud koncentrace nedosahuje požadovaných 82%, ale např. jen 78% = vypustit celé", "images": [], "videos": []}, {"id": "e458", "text": "při výměně kompresoru - zavřít ventily a upustit zbytkový vzduch přes hadice -(není výpušťák)", "images": [], "videos": []}, {"id": "e459", "text": "4. Helium - vypnout kompresor - jistič ve skříňi nad ovládáním recyklace THR3, otevřít ventil, musí být otevřený (za krytem u budíku, zelená páčka bývá natržený) + relé ve skříni CR043 - vypouští elektricky", "images": [], "videos": []}, {"id": "e460", "text": "NEBO do IND přepnout na manuál, na displaji podržet vypuštění He Gas Change pak zapnout kompresor", "images": [], "videos": []}, {"id": "e461", "text": "Na starých heliích - 2x ventil pro vysokotlak, nízkotlak, helium = musí se vyměnit jeden a vyzkoušet 50/50 pokud je pořád špatně tak je to ten druhý nebo vyměnit oba", "images": [], "videos": []}, {"id": "e462", "text": "Na nových jen jeden ventil pro media - stačí vyměnit", "images": [], "videos": []}, {"id": "e463", "text": "Problém s evakuací - neevakuuje - těsnění dveří, uvolněný jig uvnitř komory, sonda Pirana", "images": [], "videos": []}, {"id": "e464", "text": "Problém s recyklací = zaslepit, jinak se znehodnotí koncentrace helia", "images": [], "videos": []}, {"id": "e465", "text": "Maják u heliových bomb - příliš helia (má být 1. helium - kolem 29 bar, na ostatních 5 bar, 1 bar)", "images": [], "videos": []}, {"id": "e466", "text": "tlak na budíku 5 bar - měřák cca 4,7 - 7", "images": [], "videos": []}, {"id": "e467", "text": "zavřít lahev - upustit - nastavit méně", "images": [], "videos": []}, {"id": "e468", "text": "Rozebraný ventil", "images": [], "videos": []}, {"id": "e469", "text": "pružina, sedlo ventilu, silonová čepička", "images": ["Helium_19.jpg"], "videos": []}, {"id": "e470", "text": "měnit O-kroužek, čepičku, kroužek se 4 výběžky         (pokud jsou všechny 4 OK - tak se může nechat)", "images": [], "videos": []}, {"id": "e471", "text": "zpětná klapka - povolit ve svěráku, v půlce povolí", "images": [], "videos": []}, {"id": "e472", "text": "ventily sestavovat a instalovat opatrně - pak se nepozná hned jestli jsou funkční", "images": [], "videos": []}, {"id": "e473", "text": "Tlak v komoře", "images": [], "videos": []}, {"id": "e474", "text": "do leva saje, do prava vyrovnává - musí se dostat pod zelenou a pak zpět pod červenou", "images": [], "videos": []}, {"id": "e475", "text": "Jak klesá evakuace - pomalu/rychle", "images": [], "videos": []}, {"id": "e476", "text": "ručička musí jít pod zelenou (hranice jde nastavit) co nejníže", "images": [], "videos": []}, {"id": "e477", "text": "pokud ručička se ani nepohne (nebo jen málo)- neevakuuje:", "images": [], "videos": []}, {"id": "e478", "text": "nevyhodnocuje sonda Pirana, těsnění dveří, uvolněný jig uvnitř komory", "images": [], "videos": []}, {"id": "e479", "text": "propouští ventil - pokud projde na vysokotlak - OK, pak helium - OK, pak nízkotlak - a nepadá dolů = problém ventil GVN nízkotlak", "images": [], "videos": []}, {"id": "e480", "text": "u ventilu může propouštět zpětná klapka", "images": [], "videos": []}, {"id": "e481", "text": "když jde ručička dolů a cukne zpět = problém je ventil na jiné komoře - propouští vzduch", "images": [], "videos": []}, {"id": "e482", "text": "když na všech = centrální ventil", "images": [], "videos": []}, {"id": "e483", "text": "Tlak v kondenzátoru - evakuace pro všechny", "images": [], "videos": []}, {"id": "e484", "text": "nejde ručička pod zelenou = problém ventil, POZOR - nemusí být problém přímo ve ventilu na dané komoře→", "images": [], "videos": []}, {"id": "e485", "text": "→vyměnit→když je stále problém - vyměnit na další komoře", "images": ["Helium_22.jpg"], "videos": []}, {"id": "e486", "text": "Heliot", "images": [], "videos": []}, {"id": "e487", "text": "vyhodnocuje koncentraci (pozadí) v komoře: L -spodní limit (aby se vůbec rozjely komory), S, H - horní limit", "images": [], "videos": []}, {"id": "e488", "text": "když nic nejde (ani zavřít dveře na všech komorách, ale závory ok), hodnota L - spodní min. limit pro rozjetí heliotu - jaké hodnoty vyhodnocuje→", "images": [], "videos": []}, {"id": "e489", "text": "→pokud jsou hodnoty vyšší než limitní (asi 3,3 x 10-9)  je znečištěný heliot = restart heliotu - do Ručně→Stop test (na heliotu)→Stop→potom vypnout heliot (u starých = bez displeje nahoře se může vypnout ihned)", "images": [], "videos": []}, {"id": "e490", "text": "nebo zvednout hodnotu L - 3,4 x 10-9 - po čase vrátit zpět", "images": [], "videos": []}, {"id": "e491", "text": "dole přepnout do Ručně - pak jdou měnit hodnoty, nové helioty změnit nahoře na heliotu", "images": [], "videos": []}, {"id": "e492", "text": "nahození trvá asi 15 min.", "images": [], "videos": []}, {"id": "e493", "text": "ovládání heliotu dole - VENT - červené tlačítko - ovládá ventil u heliotu, pro manuální ovládání - vypnout ISV a HLD→pak zmáčknout VENT", "images": [], "videos": []}, {"id": "e494", "text": "TEST - zapne testování", "images": [], "videos": []}, {"id": "e495", "text": "někdy (2. Helium) se nechce na zobrazovači dole (to Háčko) ukázat to co má = Helium Leak Test→vypnout (restartovat) i helium", "images": [], "videos": []}, {"id": "e496", "text": "→pak znovu zapnout→Kalibrace→Automaticky→Automatický start", "images": [], "videos": []}, {"id": "e497", "text": "2. Helium - 2x měřák koncentrace (Sailer, Celomat) - pokud Celomat je NG  - po zadání hesla na ovládacím panelu jde přepnout na Sailer", "images": [], "videos": []}, {"id": "e498", "text": "musí být zaplé dva spínače", "images": [], "videos": []}, {"id": "e499", "text": "2. Helium - přehřívání chyba recyklace", "images": [], "videos": []}, {"id": "e500", "text": "Přehřátí ve skříni s kompresory - ventilátor odtahu V 4.2 na sloupu je jistič, jinak kanalis", "images": [], "videos": []}, {"id": "e501", "text": "Výměna Haug I.stupeň Helium 2", "images": [], "videos": []}, {"id": "e502", "text": "5 - 7 bar", "images": [], "videos": []}, {"id": "e503", "text": "vypnout HE + recyklaci, zavřít kalibrační plyn - dole, vysokotlak, nízkotlak, 2x voda, helium", "images": [], "videos": []}, {"id": "e504", "text": "uvnitř: zavřít ventil od flašek (modrá izolačka) které jsou uvnitř, nahoře nad skříní vypustit ventilem helium (na manometru klesne ručička)", "images": [], "videos": []}, {"id": "e505", "text": "Vývěva u heliotu (malá) - když se odpojí/nepojede - nevadí, nic neovlivní", "images": [], "videos": []}, {"id": "e506", "text": "když jede je horká", "images": [], "videos": []}, {"id": "e507", "text": "když bude špatná - heliot bude špatně vyhodnocovat", "images": [], "videos": []}, {"id": "e508", "text": "POZOR např. motor u vývěvy měl otočené fáze (sice v obou směrech vrtulka saje vzduch = chladí), ale heliot špatně vyhodnocuje", "images": [], "videos": []}, {"id": "e509", "text": "Dveře - nahoře sonda, vedle snímač ze shora", "images": [], "videos": []}, {"id": "e510", "text": "když se nastavují dveře horní pozice, musí se zablokovat v rozvaděči - spínač", "images": [], "videos": []}, {"id": "e511", "text": "výměna pístu udveří - do Ručního→zvednout dveře→zapřít dveře→vypnout čerpadla→vypnout vzduch", "images": [], "videos": []}, {"id": "e512", "text": "Zaseklé dveře v mezipoloze", "images": [], "videos": []}, {"id": "e513", "text": "do ručního→smazat chybu resetem→v rozvaděči jistič pro zkušební ventily→na komoře zavřít a otevřít dveře - rozhýbat je", "images": [], "videos": []}, {"id": "e514", "text": "pokud nejde do Automaticky (nechce zezelenat), musí se postupně na všech komorách vypustit sběrnice= ventil GVL a postupně přepínat komory 1,2,3,4", "images": [], "videos": []}, {"id": "e515", "text": "Kompresory", "images": [], "videos": []}, {"id": "e516", "text": "první natlačí na 16bar, druhý dojede na 43bar", "images": [], "videos": []}, {"id": "e517", "text": "problém: jak moc nenapouští první nebo druhý - který je třeba vyměnit", "images": [], "videos": []}, {"id": "e518", "text": "Vývěva", "images": [], "videos": []}, {"id": "e519", "text": "podle Ampermetr vakuov. čerpadla - 1, 2, 3", "images": [], "videos": []}, {"id": "e520", "text": "bez zátěže kolem 10A - když bude méně na nějakém měřáku (všechny 3 by se měly pohybovat stejně) a vývěva nebude horká:", "images": [], "videos": []}, {"id": "e521", "text": "NG - motor nebo silonové těsnění mezi motorem a vývěvou nebo vývěva", "images": [], "videos": []}, {"id": "e522", "text": "když je nefunkční (není horká) - v 99% problém v motoru - 4x imbus na motoru + silou oddělit (kopnout)", "images": [], "videos": []}, {"id": "e523", "text": "Časovač", "images": [], "videos": []}, {"id": "e524", "text": "pokud je zaplý na Auto - chce se v nastavený čas zapnout/vypnout", "images": [], "videos": []}, {"id": "e525", "text": "nesmí být na Auto", "images": [], "videos": []}, {"id": "e526", "text": "5. Helium", "images": [], "videos": []}, {"id": "e527", "text": "HP tank underpressure - heliová nádrž pod krajní mezí tlaku (kompesor nedostal signál k dotlakování)", "images": [], "videos": []}, {"id": "e528", "text": "→pod displejem do Manuálu + na komorách→na displeji Menu→Manuál→podržet LW pressure - natlakuje (stáčí chvíli)", "images": [], "videos": []}, {"id": "e529", "text": "Heslo: 3019", "images": [], "videos": []}, {"id": "e530", "text": "Koncentrace nízká", "images": [], "videos": []}, {"id": "e531", "text": "má spínat kompresor, ale nesepne = natlakovat hélium ručně", "images": [], "videos": []}, {"id": "e532", "text": "Dopuštění: Funkce→Dopuštění přes nizkotlak (sledovat vyšší hodnotu - kolem 4,0 Mpa)", "images": [], "videos": []}, {"id": "e533", "text": "Vypuštění:Funkce→Vypuštění přes vysokotlak", "images": [], "videos": []}, {"id": "e534", "text": "Funkce→Detekce koncentrace→Reset→přepnot do Auto (podržet obě tlačítka Auto)", "images": [], "videos": []}, {"id": "e535", "text": "když nejde = tak shodit celé", "images": ["Helium_20.jpg", "Helium_21.jpg"], "videos": []}, {"id": "e536", "text": "Chyba koncentrace", "images": [], "videos": []}, {"id": "e537", "text": "po staru: vypnout celé helium, upustit (vypnout jistič 22A, pak vypustit)", "images": [], "videos": []}, {"id": "e538", "text": "nově: změřit koncentraci→Nastavení parametry→Nizká hodnota koncentrace - změnit na nižší hodnotu (zbavit se tak chyby)→upustit přes displej→změřit znovu→vrátit zpět hodnotu", "images": [], "videos": []}, {"id": "e539", "text": "Restart helia - podržet na displeji Vypnout", "images": [], "videos": []}, {"id": "e540", "text": "Dveře helium 5", "images": [], "videos": []}, {"id": "e541", "text": "otočené přitlačení a vyklopení, do angličtiny (v Čj obráceně)", "images": [], "videos": []}, {"id": "e542", "text": "jinak přes elektroventily", "images": [], "videos": []}, {"id": "e543", "text": "3. Helium - údržba", "images": [], "videos": []}, {"id": "e544", "text": "Seiler - druhé dveře - zavřít přívod vzduchu (v prvních dveřích - označeno žlutá 4) od kompresoru a vypustit (druhé dveře ventil žlutý C)", "images": [], "videos": []}, {"id": "e545", "text": "na budíku spadne ručička", "images": [], "videos": []}, {"id": "e546", "text": "oddeklovat strany→vysát olej (vysavač ve skladu)→dolít olej (horní hranice = horní kraj hrdla, dolní = dolní kraj)", "images": [], "videos": []}, {"id": "e547", "text": "výměna po určitém opotřebení:", "images": [], "videos": []}, {"id": "e548", "text": "vzduchový filtr - 3x imbus (máznout bílou vazelínou) + o-kroužek (bílou vazelínou), šrouby potom nedotahovat na krev", "images": [], "videos": []}, {"id": "e549", "text": "uhlíkový filtr - nedotahovat na krev jinak praskne", "images": [], "videos": []}, {"id": "e550", "text": "olejový filtr - vyšroubovat, nový nalít olej", "images": [], "videos": []}, {"id": "e551", "text": "vyfoukat chladič za olejovým filtrem", "images": [], "videos": []}, {"id": "e552", "text": "vývěvy - kontrola sítek pod vlnovcem - o-kroužky bílou vazelínou", "images": [], "videos": []}, {"id": "e553", "text": "komory - otřít těsnění/vyměnit", "images": [], "videos": []}, {"id": "e554", "text": "3. Helium - chyba koncentrace", "images": [], "videos": []}, {"id": "e555", "text": "kouknout k lahvím na recyklaci - panel -> vyresetovat chyby", "images": [], "videos": []}, {"id": "e556", "text": "Nechce pustit He - do ručního a zmáčknout ISV(zastavit) a HLD (zapnout) upravit L - střední hodnota navolit kolečkem šipkama najít zvýšit ( z -9 na -8) potvrdit a mode L auto ranch", "images": [], "videos": []}, {"id": "e557", "text": "3. Helium - celý stroj se zastaví a musí se opět zapnout (vypadnou kontrolky na pro nějakou komoru)", "images": [], "videos": []}, {"id": "e558", "text": "nestíhá natlačit helium (většinou jedou na všechny komory) - zkontrolovat na displeji recyklace jak stíhá natlačit", "images": [], "videos": []}, {"id": "e559", "text": "kontrola kompresorů - I. a II.stupeň jestli natlačí a vypne - pak jsou OK", "images": [], "videos": []}, {"id": "e560", "text": "pokud vše OK - nestíhá kapacitně rychlost na 4 komory = lze snížit hodnoty na nádobě 3 kdy už začně vyrábět vyšší konečný tlak (z 34bar na 31bar)", "images": [], "videos": []}, {"id": "e561", "text": "ale POZOR na komorách hlídáno digitálem minimální hodnota tlaku helia = nelze snížit moc jinak už je chyba helia", "images": [], "videos": []}, {"id": "e562", "text": "digitál - upraveno v programu IT", "images": ["Helium_23.jpg"], "videos": []}, {"id": "e563", "text": "TEST", "images": [], "videos": []}, {"id": "e564", "text": "Program v noťasu - 123", "images": [], "videos": []}, {"id": "e565", "text": "settings - měření v torrech", "images": [], "videos": []}, {"id": "e566", "text": "měření po 1s", "images": [], "videos": []}, {"id": "e567", "text": "ukládání nebo NE", "images": [], "videos": []}, {"id": "e568", "text": "hodnota pod -2 je SUPER", "images": [], "videos": []}, {"id": "e569", "text": "hodnota -1,75 - ještě ok", "images": [], "videos": []}, {"id": "e570", "text": "hodnota -1,5 - problém = vyčistit sítka", "images": [], "videos": []}, {"id": "e571", "text": "Zapínání", "images": [], "videos": []}, {"id": "e572", "text": "panel (displej) recyklace", "images": [], "videos": []}, {"id": "e573", "text": "vyresetovat tlačítky + na displeji Reset poruch", "images": [], "videos": []}, {"id": "e574", "text": "4. Helium - údržba", "images": [], "videos": []}, {"id": "e575", "text": "černý kompresor - zavřít hlavně horní černý ventil (zašroubovat) a páka - přívod naproti černému", "images": [], "videos": []}, {"id": "e576", "text": "když střílí - ucpaná hlava nebo přívod k hlavě z bandy vzduchu", "images": [], "videos": []}, {"id": "e577", "text": "Nový kompresor - Nádoba před kompresorem - pokud padá pod -10 tak nastavit vyšší tlak dodávaného  čistého helia. Ale ne zase příliš - pojistný ventil jen na 0.4bar", "images": [], "videos": []}, {"id": "e578", "text": "Nastavení snímačů tlaku vody - za vývěvami pro evakuaci (třemi nahoře) je černá krabička - šroubek který se má pohybovat může být zarezlý", "images": [], "videos": []}, {"id": "e579", "text": "Seilery", "images": [], "videos": []}, {"id": "e580", "text": "poznat že nefunguje - jeden zavřít přívod - a jestli tlačí druhý a naopak", "images": [], "videos": []}, {"id": "e581", "text": "6. Helium", "images": [], "videos": []}, {"id": "e582", "text": "labtech", "images": [], "videos": []}, {"id": "e583", "text": "2816", "images": [], "videos": []}, {"id": "e584", "text": "- v ručním režimu je když ukazuje Auto", "images": [], "videos": []}, {"id": "e585", "text": "- odhlášení - přepnout do Auto a odhlásit, jinak je stále v ručním", "images": [], "videos": []}, {"id": "e586", "text": "- vysokotlaký vzduch pomalu otvírat uzávěr", "images": [], "videos": []}, {"id": "e587", "text": "- pro vypuštění - zavřít přívod a otevřít výpušťák v rozvaděči v heliu", "images": [], "videos": []}, {"id": "e588", "text": "ve stanby rozjet tlačítkem na komoře", "images": [], "videos": []}, {"id": "e589", "text": "Kalibrace", "images": [], "videos": []}, {"id": "e590", "text": "jde udělat pro jednu komoru samostatně, vložit kus až se rozbliká modrý maják (ne když svítí)", "images": [], "videos": []}, {"id": "e591", "text": "vložit kus ->Utěsnit -> uzavřít ventil vypouštění (pravý, na obrázku)->Zavřít dveře -> napustit->He/vysokotlakem (Air 180bar, ale stačí jen ťuknout nemusí se natlakovat na plno)->odfouknout pravým ventilem(levý jde do haly, velká rána)", "images": ["Helium_43.jpg"], "videos": []}, {"id": "e592", "text": "Vypuštění balónu nahoře nad skříní.", "images": [], "videos": []}, {"id": "e593", "text": "Pro odtlakovani soustavy - zavřít přívod od láhve He a VT, odtlakovat ve skříni He a VT", "images": [], "videos": []}, {"id": "e594", "text": "Po výpadku", "images": [], "videos": []}, {"id": "e595", "text": "může být v mezipoloze a nelze otevřít komora (je v ní podtlak)", "images": [], "videos": []}, {"id": "e596", "text": "přepnout na danou komoru ->ventilem GVL odpustit tlak ze sběrnice", "images": [], "videos": []}, {"id": "e597", "text": "pokud nepomůže -> ventilem AVV vyrovnat tlak v komoře", "images": [], "videos": []}, {"id": "e598", "text": "pokud nepomůže ani to -> nejdříve zmáčknout RV - dovysaje komoru -> vypnout RV -> dorovnat tlak přes AVV", "images": [], "videos": []}, {"id": "e599", "text": "2. Helium - přepnutí na druhý měřák koncentrace", "images": [], "videos": []}, {"id": "e600", "text": "na Calomat viz. Video  Práce Helium", "images": ["Helium_33.jpg", "Helium_34.jpg"], "videos": []}, {"id": "e601", "text": "V1 nádoba nad rozvaděčem", "images": [], "videos": []}, {"id": "e602", "text": "V2 sailer", "images": [], "videos": []}, {"id": "e603", "text": "V3 dvě lahve v rozvaděči", "images": [], "videos": []}, {"id": "e604", "text": "Výměna ventilů pro evakuaci (velké UV)", "images": [], "videos": []}, {"id": "e605", "text": "Dveře na komorách otevřít ->Ruční + Automat + Pumpy stop-> zavřít nízkotlak a odtlakovat", "images": [], "videos": []}, {"id": "e606", "text": "Vyndat sítko ze spodku komory, položit pod otvor hadr", "images": [], "videos": []}, {"id": "e607", "text": "Odšroubovat ventil, vyčistit přírubu, namazat O-kroužek vazelínou (bílá na vacuum)", "images": [], "videos": []}, {"id": "e608", "text": "Repase ventilu - vyměnit O- kroužky a namazat potravinářskou vazelínou", "images": [], "videos": []}, {"id": "e609", "text": "Helium 1", "images": [], "videos": []}, {"id": "e610", "text": "Nízká koncentrace - vypuštění do komína přes GVB ventil na rozvaděči - ventily - podržet než začne vypouštět", "images": [], "videos": []}, {"id": "e611", "text": "Po výměně lahve může se objevit chyba Koncentrace - lze odstranit tak, že na měřáku koncentrace nastavím SPAN (čárkovaný sloupec) výše než je druhá limitní čárka - Reset a poté vrátit", "images": ["Helium_45.jpg"], "videos": []}, {"id": "e612", "text": "Helium 6", "images": [], "videos": []}, {"id": "e613", "text": "propíchnout v gumičce střed - nemusí vycházet He test", "images": [], "videos": []}, {"id": "e614", "text": "profouknout slabou trubičku - neprochází na profuk", "images": [], "videos": []}, {"id": "e615", "text": "Pro ověření jestli je dobrá hadice - propojit rovnou vstup na výstup. Bude se měřit jen hadice", "images": [], "videos": []}, {"id": "e616", "text": "Vyřazení vysokotlaku a profuku - nastavit na 0 Throughput a Prooftest", "images": ["Helium_44.jpg"], "videos": []}, {"id": "e617", "text": "He6 hodnota dynamického koeficientu vysoká - pro přepsání = monitor na liště -> klávesnice přepsat", "images": [], "videos": []}, {"id": "e618", "text": "Chyba koncentrace helia - pokud je balón vypuštěný (nesvítí snímač pro minimum)", "images": [], "videos": []}, {"id": "e619", "text": "= zavřít láhev helia, propojit hadičku napřímo do balónu -> pustit helium. Až se dostane na displeji nad snímač (zelená OK), propojit hadičky zpět přes ventil. Potom pustit kompresor He", "images": [], "videos": []}]}, {"id": "c9", "name": "Barva", "entries": [{"id": "e620", "text": "Neprůchodné trysky", "images": [], "videos": []}, {"id": "e621", "text": "Profouknout vzduchem, vyměnit čerpadlo", "images": [], "videos": []}, {"id": "e622", "text": "Aby stříkala pistole č.7 - musí být program 26", "images": [], "videos": []}, {"id": "e623", "text": "Čerpadlo barvy", "images": [], "videos": []}, {"id": "e624", "text": "čištění - očistit plochy", "images": [], "videos": []}, {"id": "e625", "text": "dotahovat v pouzdrech jen s citem na kuličku", "images": [], "videos": []}, {"id": "e626", "text": "gumičky zpět, trubičky správně na osazení", "images": [], "videos": []}, {"id": "e627", "text": "Rozvaděč", "images": [], "videos": []}, {"id": "e628", "text": "vyresetování chyby - zmáčknout obě tlačítka - Porucha potvrzena + Nouzové vypnutí potvrzeno - jinak se jen smaže chyba a další poruchu nebude hlásit", "images": [], "videos": []}, {"id": "e629", "text": "Hořák na schodech", "images": [], "videos": []}, {"id": "e630", "text": "obě tlačítka zaplá na 1 (jako kompresory, jedno na částečnou teplotu, druhé na koncovou)", "images": [], "videos": []}, {"id": "e631", "text": "na rozvaděči svítí Porucha hořáku - nahoře na schodech za dvěmi tlačítky svítí červeně pod plexi = zmáčknout plexi - to vypne hořák→", "images": [], "videos": []}, {"id": "e632", "text": "→reset chyby na rozvaděči→pak zapnout napřed první tlačítko (pravé), chvíli počkat a potom druhé", "images": [], "videos": []}, {"id": "e633", "text": "Pokud píše chybu a nejde vyresetovat →vytáhnout ze zásuvky", "images": ["Barva_47.jpg", "Barva_48.jpg"], "videos": []}, {"id": "e634", "text": "Nouzové vyjetí", "images": [], "videos": []}, {"id": "e635", "text": "dopravník pojede rychleji než normálně", "images": [], "videos": []}, {"id": "e636", "text": "musí být nahozený záložní zdroj - na rozvaděči svítí kontrolka Napětí z NZ", "images": [], "videos": []}, {"id": "e637", "text": "sundat plomby, zapnout na ON motor dopravníku 90M1 nebo 90M2 (jede jen jeden, druhý už není)", "images": [], "videos": []}, {"id": "e638", "text": "U dveří - u řídících panelů", "images": [], "videos": []}, {"id": "e639", "text": "na starém - jeden  klíč musí být vodorovně (ten dál), druhý mírně šikmo doprava", "images": [], "videos": []}, {"id": "e640", "text": "na novém - po přeprnutí do Ručně - lze manipulovat", "images": [], "videos": []}, {"id": "e641", "text": "Škrabka- nemá koncové spínáče ! - někdo musí hlásit kde je", "images": [], "videos": []}, {"id": "e642", "text": "Ventilátor - nastavení oklepu", "images": [], "videos": []}, {"id": "e643", "text": "Při vyhodnocení CO2 - PRYČ", "images": [], "videos": []}, {"id": "e644", "text": "Vzadu u dveří, u rozvaděčů - bomba, u ní čidla,fotonka = nesmí se jiskřit, fotit - spustí se alarm", "images": [], "videos": []}, {"id": "e645", "text": "Když nejde rozjet dopravník", "images": [], "videos": []}, {"id": "e646", "text": "Propojit v rozvaděči na bezpečnostním relé 23 s 33 - drátek dole v rozvaděči", "images": [], "videos": []}, {"id": "e647", "text": "Pokud barva nejede více dní - vybijou se kondenzátory a musí se nabudit = propojit + s označeným kontaktem", "images": ["Barva_49.jpg", "Barva_50.jpg", "Barva_51.jpg"], "videos": []}, {"id": "e648", "text": "Tlak do čerpadel 6,5 barů před vstupem", "images": ["Barva_46.jpg"], "videos": []}]}, {"id": "c10", "name": "Příprava", "entries": [{"id": "e649", "text": "Heslo: 1121", "images": [], "videos": []}, {"id": "e650", "text": "TBC/8W0 - krimpování příliš blízko přepážce - lze nastavit nahoře na pneuválci", "images": [], "videos": []}, {"id": "e651", "text": "zatlačení víčka - nastavení na pneuválci, povolit kontra", "images": [], "videos": []}, {"id": "e652", "text": "Utahovák", "images": [], "videos": []}, {"id": "e653", "text": "konektor Lemo", "images": ["Příprava_52.jpg"], "videos": []}, {"id": "e654", "text": "Odpojit si konektor z vyhodnocovače uvnitř rozvaděče", "images": [], "videos": []}, {"id": "e655", "text": "Po zapájení případně izolovat kontakty od sebe - izolačka mezi zapájené konektory", "images": [], "videos": []}]}, {"id": "c11", "name": "Sessler", "entries": [{"id": "e656", "text": "srovnání vždy přes pozici 5 (REFERENČNÍ) - jinak vyjede ven", "images": [], "videos": []}, {"id": "e657", "text": "pokud nejde hnout dopředu/dozadu - nahoře na krabici (pojezd), uprostřed indukční čidlo - aby přiznávalo (např. položit klíč na něj) - pak jde hnout", "images": [], "videos": []}, {"id": "e658", "text": "pokud nejde hnout nahoru/dolů - dolů musí mít naložený koš - jinak se nepojede = zaslepit čidlo pro detekci koše", "images": [], "videos": []}, {"id": "e659", "text": "senzor pro detekci koše (když se zastaví nad jiným košem plný) neotvírat v Automatu→přepnout do Ručně", "images": [], "videos": []}, {"id": "e660", "text": "horní hranice detekce pojezdu (nahoru), senzor uvnitř oranžového oplechování", "images": [], "videos": []}, {"id": "e661", "text": "první vana nevypouštět, přečerpat do sousedící", "images": [], "videos": []}, {"id": "e662", "text": "kyselinu nevypouštět do ČOVky", "images": [], "videos": []}, {"id": "e663", "text": "tlačítko pro stránku s pojezdem - druhé z leva (omačkané)", "images": [], "videos": []}, {"id": "e664", "text": "na displeji při manipulaci držet vždy nebo nahoru/dolů + brzdu (popsané vozík - poslední) - jinak se nehne", "images": [], "videos": []}, {"id": "e665", "text": "srovnat koše podle rozmístění: 3 - 6 - 8 - 9", "images": [], "videos": []}, {"id": "e666", "text": "na displeji musí být kolečka (ne hvězdičky) = přes menu do chyb a vyresetovat", "images": [], "videos": []}, {"id": "e667", "text": "listování v Menu - šipka na displeji v pravo = tlačítko vozík", "images": [], "videos": []}, {"id": "e668", "text": "může být i vypadlý frekvenční měnič", "images": [], "videos": []}, {"id": "e669", "text": "pak do Auto→Potvrzení (zelené tlačítko) na ovládacím panelu", "images": [], "videos": []}, {"id": "e670", "text": "Pohyb košů", "images": [], "videos": []}, {"id": "e671", "text": "- do Ruční → přihlásit se na displeji 1022→ stránka pro pohy (tlačítko druhé z leva, omačkané)→zadat číslo vany, potvrdit enter a tlačítko odpovídající pro pohyb (vozík)→počkat až ukáže číslo pozice", "images": [], "videos": []}, {"id": "e672", "text": "- pohyb nahoru/dolů podržet brzdu (koš) + pohyb nahoru nebo dolů a počkat než ukáže OK", "images": [], "videos": []}, {"id": "e673", "text": "- pokud nejde hýbat - může se rozhýbat přes referenční pohyb = podržet tlačítko brzda (koš)+ pohyby vlevo/vpravo", "images": [], "videos": []}, {"id": "e674", "text": "lze pohnout i ručně - volnit brzdu v rozvaděči přes stykač a pohnout pojezdem, POZOR pokud se uvolní brzda pro nahoru/dolů letí rychle dolů", "images": [], "videos": []}, {"id": "e675", "text": "stykači si lze kontrolovat jestli se koše točí v jednotlivých vanách i nahoře", "images": [], "videos": []}, {"id": "e676", "text": "do výchozí pozice by se mělo ukončovat když jede na první pozici pak přepnout do 0", "images": [], "videos": []}, {"id": "e677", "text": "Separátor", "images": [], "videos": []}, {"id": "e678", "text": "Alkalický separátor | Kyselý separátor", "images": [], "videos": []}, {"id": "e679", "text": "Vyp | Zap | Vyp | Zap", "images": [], "videos": []}, {"id": "e680", "text": "Automat", "images": [], "videos": []}, {"id": "e681", "text": "Manuál", "images": [], "videos": []}, {"id": "e682", "text": "při zapnutí do Manual - doplňuje stále", "images": [], "videos": []}, {"id": "e683", "text": "v Automat - hlídá sonda", "images": [], "videos": []}, {"id": "e684", "text": "když doplňuje stále - zavřít ventil s vodou", "images": [], "videos": []}, {"id": "e685", "text": "Čerpadlo u headerfluxeru", "images": [], "videos": []}, {"id": "e686", "text": "při zanesení (nečerpá), vyčistit dvě zpětné klapky", "images": [], "videos": []}, {"id": "e687", "text": "Výměna koše", "images": [], "videos": []}, {"id": "e688", "text": "- do pozice č. 9, vysokým paleťákem pod koš, nadzvednout a přetáhnout na paleťák", "images": [], "videos": []}, {"id": "e689", "text": "- když je na koši odbržděna brzda (pokud je motor odkloněn) - zafixovat popruhem", "images": [], "videos": []}, {"id": "e690", "text": "Pustit páru na sessleru", "images": [], "videos": []}, {"id": "e691", "text": "Pomalu otevírat velké kolo vlevo, potom pomalu velké vpravo", "images": [], "videos": []}, {"id": "e692", "text": "Když je zavřeno v kotelně - pustit Do výroby", "images": [], "videos": []}, {"id": "e693", "text": "Nastavení sondy, úprava offsetů na regulátoru a zapisovači", "images": [], "videos": []}, {"id": "e694", "text": "Na zapisovači najít I/O a dále úplně dole", "images": [], "videos": []}, {"id": "e695", "text": "Regulátor odemčení", "images": ["Sessler_58.jpg"], "videos": []}, {"id": "e696", "text": "Regulátor nastavení  - přepnutí do adjustment level", "images": ["Sessler_59.jpg"], "videos": []}, {"id": "e697", "text": "Zapojení motorů ventilátoru", "images": [], "videos": []}, {"id": "e698", "text": "Zapojit na nižší otáčky - NEDÁVAT nikam klemu", "images": [], "videos": []}, {"id": "e699", "text": "Připojit fáze na U1, V1, W1", "images": [], "videos": []}, {"id": "e700", "text": "U2, V2, W2 nechat VOLNÉ", "images": [], "videos": []}]}, {"id": "c12", "name": "Nýtovačka", "entries": [{"id": "e701", "text": "Odchází rychle pistole - zkontolovat stolici pro pistoli a stolici pro stůl, nýt musí jít do chladiče rovně (ne šikmo)", "images": [], "videos": []}, {"id": "e702", "text": "Nastavení pistole - délka 79 mm", "images": [], "videos": []}]}, {"id": "c13", "name": "Ohýbačka", "entries": [{"id": "e703", "text": "Zaseknutí v Kalibraci - vypnout - přepnuto v Auto - spustit Kalibraci (musí se dokončit)", "images": [], "videos": []}, {"id": "e704", "text": "Heslo: 42", "images": [], "videos": []}, {"id": "e705", "text": "nejde do výchozí pozice: Menu - Výchozí pozice - heslo: 1", "images": [], "videos": []}, {"id": "e706", "text": "kontrola čidel jestli jsou OK (táhlo pro filtr, doraz na konec, písty)", "images": [], "videos": []}, {"id": "e707", "text": "čidlo na pistoli -nechat vyměnit pistol, vyzkoušet mimo stroj: připojit na vzduch - čidlo sepne při cvaknutí", "images": [], "videos": []}, {"id": "e708", "text": "Nastavit kameru", "images": [], "videos": []}, {"id": "e709", "text": "Notebook - program na nastavení", "images": [], "videos": []}, {"id": "e710", "text": "přepnuto mimo wifi (jinak bere wifi)", "images": [], "videos": []}, {"id": "e711", "text": "program SOPAS", "images": [], "videos": []}, {"id": "e712", "text": "kliknout na tři body vedle online", "images": [], "videos": []}, {"id": "e713", "text": "na stroji : BARVA - ANO/NE - rozdíl kvůli kameře a který referenční obrázek to je", "images": [], "videos": []}, {"id": "e714", "text": "pokud je jiné světlo lze nastavit intensitu EDIT a nastavit ukazatel aby se zbarvil do zelena", "images": [], "videos": []}, {"id": "e715", "text": "poté potvrdit zase EDIT", "images": [], "videos": []}, {"id": "e716", "text": "když je kamera úplně mimo -může se sledovat nepřetržitě, ale potom zase vypnout", "images": [], "videos": []}, {"id": "e717", "text": "Táhlo", "images": [], "videos": []}, {"id": "e718", "text": "horní část se musí hýbat, ale nevypadnout dole = povystrčit zespodu→dotáhnout červ", "images": [], "videos": []}, {"id": "e719", "text": "POZOR na vypadlý magnet zespodu", "images": [], "videos": []}, {"id": "e720", "text": "nahoře červ pro pružení hlavičky", "images": [], "videos": []}, {"id": "e721", "text": "vše funguje (senzory OK), ale dioda se nerozsvítí zeleně (jen problikne) - vypnout a znovu kalibrovat", "images": [], "videos": []}, {"id": "e722", "text": "když se nerozsvítí dioda - není přiznaný předchozí krok, může svítit stále spodní snímač", "images": [], "videos": []}, {"id": "e723", "text": "na táhle - jedno čidlo (větší) pro detekci, že je na místě a druhé (meší), že není moc blízko - nesmí svítit v pracovní pozici", "images": [], "videos": []}, {"id": "e724", "text": "ohýbačka dole - vrátit do kroku a stisknout tlačítka", "images": [], "videos": []}, {"id": "e725", "text": "pistole nevypne po dotažení zátky - může ucházet vzduch nebo seřídit vyhodnocovač (malý šroubek na vyhodnocovači)", "images": [], "videos": []}, {"id": "e726", "text": "Ohýbačka TBC - po úpravě kamery je ještě chyba na displeji = vymazat", "images": [], "videos": []}, {"id": "e727", "text": "Zaseklý výrobek", "images": [], "videos": []}, {"id": "e728", "text": "odpojit el. ovládání ventilu, bývá to druhý od spodu vpravo - zmáčknout ho ručně", "images": [], "videos": []}, {"id": "e729", "text": "pokud  ohýbačku už neodpojili nebo nevypli může fungovat návrat do Základní pozice přes displej", "images": [], "videos": []}, {"id": "e730", "text": "Heslo: 42", "images": [], "videos": []}, {"id": "e731", "text": "navolit Základní pozice, přepnuto do Auto, odmáčklá závora- zmáčknout F2 a pak tlačítko na ohýbačce Start", "images": [], "videos": []}, {"id": "e732", "text": "je jen jeden pokus", "images": [], "videos": []}, {"id": "e733", "text": "Pistole nechce přiznat dotažení", "images": [], "videos": []}, {"id": "e734", "text": "v Menu přepnout vzduchovou pistoly do ručního v Nastavení hodnot pak chytit do kleští a několikrát procvakat (aby se chytla), a zpět přepnout do automatu", "images": [], "videos": []}, {"id": "e735", "text": "Nechce se otevřít", "images": [], "videos": []}, {"id": "e736", "text": "jádro doděláno, závora OK, tlačítka OK (lze vidět v PLC)", "images": [], "videos": []}, {"id": "e737", "text": "vypnout závoru - v rozvaděči FU1/FU2 možná FU3 vysunout pojistku poté znovu zastrčit. Odmáčknout závoru a jádro dostat ven", "images": [], "videos": []}, {"id": "e738", "text": "Bliká červeně kontrolka - vypnout a rychle opět zapnout (počkat až zhasnout relátka) - zbavím se chyby a nemusí se opět dělat kalibrace", "images": [], "videos": []}, {"id": "e739", "text": "Pokud blikají dvě vedle sebe (viz. Obrázek) - tlakový snímač - vypnout a opět rychle zapnout", "images": ["Ohýbačka_60.jpg"], "videos": []}, {"id": "e740", "text": "Zavírá a otvírá se deska se zpožděním", "images": [], "videos": []}, {"id": "e741", "text": "snímač tlaku dává signál při dostatečném tlaku - lze nastavit na nižší", "images": ["Ohýbačka_61.jpg"], "videos": []}]}, {"id": "c14", "name": "Pec", "entries": [{"id": "e742", "text": "PEC 1", "images": [], "videos": []}, {"id": "e743", "text": "Preheater - hořák zapnutí uvnitř rozvaděče", "images": [], "videos": []}, {"id": "e744", "text": "Displej - Nastavení hranic teploty - krajní a provozní - když se vypne dopravník teplota prudce roste (lze nastavit vyšší hodnoty, aby nevypla celá pec = vypnou i ventilátory, hořáky atd.)", "images": [], "videos": []}, {"id": "e745", "text": "pokud se přehřívá pec a jsou nízké havarijní limity, tak vypne všechny topení a hlásí chybu", "images": [], "videos": []}, {"id": "e746", "text": "přihlásit se do zapisovače:", "images": [], "videos": []}, {"id": "e747", "text": "spravce", "images": [], "videos": []}, {"id": "e748", "text": "administrator123", "images": [], "videos": []}, {"id": "e749", "text": "v rozvaděči napsáno na druhé straně zapisovače", "images": [], "videos": []}, {"id": "e750", "text": "najít v nastavení - nastavení limitů a změnit - změnit nejvyšší limit jsou tam dva vysoké, jeden hlásí upozornění, druhý už je ten havarijní", "images": [], "videos": []}, {"id": "e751", "text": "Nastavení sjížděcího programu", "images": [], "videos": []}, {"id": "e752", "text": "zapnout programátor - otočit na 1", "images": [], "videos": []}, {"id": "e753", "text": "na víkend: na programátoru: reset (dvě tlačítka, když se zavřou dolní dvířka je popsáno Reset)", "images": [], "videos": []}, {"id": "e754", "text": "pak stisknout Program dokud nenajdu 3 apak Run", "images": [], "videos": []}, {"id": "e755", "text": "někdy stačí hned jen Run pokud je předvoleno", "images": [], "videos": []}, {"id": "e756", "text": "Pec 1 a 2 úprava teploty", "images": [], "videos": []}, {"id": "e757", "text": "Pec horní topení zóna 1 a 2. Stáhnout o 20. Dvakrát SP (aby blikalo), šipkou dolů o 20, potvrdit enter. Pak displej pro návrat", "images": [], "videos": []}, {"id": "e758", "text": "Nízký tlak vzduchu - filtr nad sušící pecí - když je zanešený může být nízký tlak vzduchu pro hořák", "images": [], "videos": []}, {"id": "e759", "text": "PEC 3", "images": [], "videos": []}, {"id": "e760", "text": "Heslo: 1111", "images": [], "videos": []}, {"id": "e761", "text": "první větráky se musí točit a chladit vodou", "images": [], "videos": []}, {"id": "e762", "text": "smazání chyby: Buzzer reset + Alarm reset", "images": [], "videos": []}, {"id": "e763", "text": "Preheater - Hořák - reset uvnitř rozvaděče (podržet na 3s Reset - červený), na rozvaděči Reset Alarm + Buzzer", "images": [], "videos": []}, {"id": "e764", "text": "změna teplot v hlavním menu - nastavení jednotlivých programů (1-4) - lze po zadání hesla přepsat teploty, když se nepřepíší hned - přepnout program a zase zpět", "images": [], "videos": []}, {"id": "e765", "text": "Program 3 - normální provoz, program 4 - odstaveno na víkend hodnoty 100°C", "images": [], "videos": []}, {"id": "e766", "text": "Když se vyndavá špunt musí se zavřít DUSÍK", "images": [], "videos": []}, {"id": "e767", "text": "VYPNUTÁ", "images": ["Pec_62.jpg", "Pec_63.jpg"], "videos": []}, {"id": "e768", "text": "Pec 3 - trysky", "images": [], "videos": []}, {"id": "e769", "text": "horní ventil - otevírací pro trysku", "images": [], "videos": []}, {"id": "e770", "text": "LIQ - flux, zbývá (gun, atomizační tlak)", "images": [], "videos": []}, {"id": "e771", "text": "Výpadek → nahození", "images": [], "videos": []}, {"id": "e772", "text": "Krátkodobý výpadek - největší rozdíl teplot o 80°C - může se zapnout ještě normálně", "images": [], "videos": []}, {"id": "e773", "text": "Dlouhodobý  - musí se dát Najížděcí program", "images": [], "videos": []}, {"id": "e774", "text": "ventilátory, sušák atd. (pravá strana rozvaděče) - vše na OFF, pak RESET → zapnout Control Power→vše zapnout na ON→", "images": [], "videos": []}, {"id": "e775", "text": "→zapnout hořáky - zapnout Ventil nouz. zastavení →přepnout na hořák č. 1 →zapnout, čekat na hodnotu 2,2µA vždy se přesvědčit, že hoří fyzicky", "images": [], "videos": []}, {"id": "e776", "text": "pokud je kolem 1,7 a padá, raději vypnout a po chvíli zkusit znovu(může vypadnout úplně - v rozvaděči zapnout relé - svítí modře - někdy chvíli počkat)", "images": [], "videos": []}, {"id": "e777", "text": "když nejde může se pilotní hořák nastavit víc/míň plynu - povolit kontra, pustit více/méně - jen o ¼ otáčky", "images": [], "videos": []}, {"id": "e778", "text": "nechce-li zapalovat může být problém filtr (nad pecí), svíčka nebo fotonka", "images": [], "videos": []}, {"id": "e779", "text": "(aby se daly zapnout hořáky musí být zaplý aspoň Sušící pec ventilátor)", "images": [], "videos": []}, {"id": "e780", "text": "Nouzové nahození", "images": [], "videos": []}, {"id": "e781", "text": "musí běžet záložní zdroj→sundat plombu→přepnout na nouzové motory", "images": [], "videos": []}, {"id": "e782", "text": "Odstavení víkend", "images": [], "videos": []}, {"id": "e783", "text": "program pec, dusík, nahodit záložní kompresor - pro napnutí dopravníku (vzduch E, F - vyp, zap)", "images": [], "videos": []}, {"id": "e784", "text": "Pec 2 - přepnout vzduchy i pro filtr splodin", "images": [], "videos": []}, {"id": "e785", "text": "Zpětná čerpadla", "images": [], "videos": []}, {"id": "e786", "text": "po výpadku nebo jiném problému - nahodit uvnitř rozvaděče", "images": [], "videos": []}, {"id": "e787", "text": "pokud jedno nejde, přepnout z Auto (Automatické střídání) na 1 nebo 2 - záleží, které je v pořádku", "images": [], "videos": []}, {"id": "e788", "text": "po výměně zavodnit a pak odvzdušnit", "images": [], "videos": []}, {"id": "e789", "text": "Preheater", "images": [], "videos": []}, {"id": "e790", "text": "když nejde hořák - hlásí přehřátí = vyndat teploměr a počkat", "images": [], "videos": []}, {"id": "e791", "text": "nahodit hořák", "images": [], "videos": []}, {"id": "e792", "text": "na Peci 1 - čidlo po rozdělení kaslíků (řezení) - levá polovina míří na odrazku (červeně svítí na odrazce), pravá polovina nesvítí na odrazce", "images": [], "videos": []}, {"id": "e793", "text": "náhradní svíčky - sklad 180209", "images": [], "videos": []}, {"id": "e794", "text": "náhradní fotonka - 180208", "images": [], "videos": []}, {"id": "e795", "text": "Pec 1", "images": [], "videos": []}, {"id": "e796", "text": "plyn - vypínání", "images": [], "videos": []}, {"id": "e797", "text": "nechat mírně natržený, ventil hlavní uzávěr", "images": [], "videos": []}, {"id": "e798", "text": "Azbil DC36 regulátor - (zmáčknutím Mode se objeví režim do kterého chci přepnout). Pokud netopí podržet Mode - tím se přepne do Automatu. Je to obráceně, to co ukazuje, do toho můžu přepínat", "images": [], "videos": []}, {"id": "e799", "text": "Přepnutí - měří O₂", "images": [], "videos": []}, {"id": "e800", "text": "pokud se mění filtry - musí se přepnout, jinak vyhodnotí a zastaví oba dopravníky", "images": [], "videos": []}, {"id": "e801", "text": "první stupeň - varování, druhý - zastaví", "images": [], "videos": []}, {"id": "e802", "text": "Hořáky neregulují Pec 1", "images": [], "videos": []}, {"id": "e803", "text": "2x jistič 102 a 103 - klidně zapnout vícekrát aby se chytily", "images": [], "videos": []}, {"id": "e804", "text": "Pec 1 a 2 úprava teploty", "images": [], "videos": []}, {"id": "e805", "text": "Pec horní topení zóna 1 a 2. Stáhnout o 20. Dvakrát SP (aby blikalo), šipkou dolů o 20, potvrdit enter. Pak displej pro návrat", "images": ["Pec_64.jpg"], "videos": []}, {"id": "e806", "text": "Upravit/zkalibrovat měření dusíku", "images": [], "videos": []}, {"id": "e807", "text": "podržet tlačítko - začna blikat hodnota, podržet šipkama kam chci upravit a hotovo", "images": [], "videos": []}, {"id": "e808", "text": "Výpadek na zkrat v obvodu", "images": [], "videos": []}, {"id": "e809", "text": "nemusí být jen na zkrat, ale i nadproud = kontrola kolik odebírá topení A na měřáku při výkonu na 100%", "images": [], "videos": []}, {"id": "e810", "text": "pokud bere moc může se ubrat výkon přes potenciometr", "images": ["Pec_65.jpg"], "videos": []}, {"id": "e811", "text": "Přehřátí", "images": [], "videos": []}, {"id": "e812", "text": "výpadek - nějaké topení dosáhlo limitu pro max. hodnoty", "images": [], "videos": []}, {"id": "e813", "text": "poklepat regulátor pro danou zónu - jestli měří správně", "images": [], "videos": []}, {"id": "e814", "text": "Reset chyby - jde pokud nejsou teploty stále mimo rozsah", "images": [], "videos": []}, {"id": "e815", "text": "Pak znovu zapnout pec", "images": [], "videos": []}, {"id": "e816", "text": "První zóna = 9 topení po třech trojicích - měření zkratu -odpojuji trojice - první a poslední přívod, když se zjistí která trojice tak pak které odpojuji jednotlivá topení od sebe", "images": [], "videos": []}, {"id": "e817", "text": "stejně tak měření - Megmetem, měřím všech 9 proti sobě (jestli není přerušené) a jednotlivé trojice proti zemi (jaký mají izolační odpor min. 1,5MΩ), potom odpojím v trojici  a zjistím které konkrétní je špatné", "images": [], "videos": []}, {"id": "e818", "text": "Kontrola vody v chladících vozících jestli je zavřeno vypouštění do jímky!!!", "images": [], "videos": []}, {"id": "e819", "text": "Tyristorový regulátor - vnitřek, může být proražený = nereguluje (jede pořád). Změřit odpor obou dvou - pokud nemá odpor = nefunkční", "images": [], "videos": []}, {"id": "e820", "text": "nebo spálená pojistka = má 100% požadavek na natápění, ale netopí", "images": [], "videos": []}, {"id": "e821", "text": "Odpor topení vůči zemi 1Mohm minimálně, nové je nekonečno, rozmezí na 20 ohm na měřáku", "images": [], "videos": []}]}, {"id": "c15", "name": "Profuk", "entries": [{"id": "e822", "text": "Heslo: 1121", "images": [], "videos": []}, {"id": "e823", "text": "5Q0, 1S0 - klíč od spodního vyhodnocovače - v rozvaděči nahoře", "images": [], "videos": []}, {"id": "e824", "text": "Pokud neprochází  a na druhém ano - vzít kontrolní kus a zjistit který je špatně", "images": [], "videos": []}, {"id": "e825", "text": "nedojížděl jig- původně by měla být úzká pružina, podložku na konci pružiny u jigu (zkrátit pružinu)", "images": [], "videos": []}, {"id": "e826", "text": "pokud je vše OK, může se změnit nastavení hodnoty průtoku - potom zapsat do ETZ", "images": [], "videos": []}, {"id": "e827", "text": "8U0 - správně model + správný klíč k modelu", "images": [], "videos": []}, {"id": "e828", "text": "nespínají tlačítka - většinou rozpínací kontakty", "images": [], "videos": []}, {"id": "e829", "text": "pokud uvnitř rozvaděče svítí chyba na Sicku - vypnout hlavním vypínačem", "images": [], "videos": []}, {"id": "e830", "text": "když se ani nezačne napouštět - mimo meze vzduch= profuk klíčkem do ručního, pak zmáčknout C, najít parametr Fill max a zvýšit (vstupní tlak), pak když už napouští (ukazuje v l/min) změnit hodnotu zpět", "images": [], "videos": []}, {"id": "e831", "text": "Starý profuk", "images": [], "videos": []}, {"id": "e832", "text": "vyzkoušet bez ucpání, potom ucpat", "images": [], "videos": []}, {"id": "e833", "text": "má nastaveno na digitálu malé rozmezí 3,98 - 4,02bar", "images": [], "videos": []}, {"id": "e834", "text": "nastavení redukčního ventilu", "images": [], "videos": []}, {"id": "e835", "text": "vedle tlakový snímač", "images": ["Profuk_66.jpg", "Profuk_67.jpg"], "videos": []}]}, {"id": "c16", "name": "Fluxery", "entries": [{"id": "e836", "text": "míchání fluxu - neotáčí se, prostříknout olejem→vyndat odvzdušňovač a pročistit vzduchem (přidržet hadrem)", "images": [], "videos": []}, {"id": "e837", "text": "Fluxer malých dílů", "images": [], "videos": []}, {"id": "e838", "text": "dveře = dole táhla", "images": [], "videos": []}, {"id": "e839", "text": "neotáčí se - nahoře spojka", "images": [], "videos": []}, {"id": "e840", "text": "nezajíždí - vzduch, špatný kontakt na elektroventilu", "images": [], "videos": []}, {"id": "e841", "text": "Fluxer u sessleru", "images": [], "videos": []}, {"id": "e842", "text": "heslo: showa", "images": [], "videos": []}, {"id": "e843", "text": "dopravník - není ve výchozí pozici = přihlášení + srovnat", "images": [], "videos": []}, {"id": "e844", "text": "chyba dopravníku = vypnout celý fluxer", "images": [], "videos": []}]}, {"id": "c17", "name": "Rozměr", "entries": [{"id": "e845", "text": "když se zmáčknou tlačítka a nic se neděje - do rozvaděče - bezpečnostní relé - pokud na něm svítí červeně chyba - FAULT→", "images": [], "videos": []}, {"id": "e846", "text": "→vypnout, znovu zapnout, pokud stále - tlačítka musí sepnout spínací i vypínací kontakty (někdy jsou na jedné straně ulomené)", "images": [], "videos": []}, {"id": "e847", "text": "Nastavení starých rozměrů 1K0", "images": [], "videos": []}, {"id": "e848", "text": "Nechce se rozjet - mimo snímače - 4 pneuválce, na každém jsou 4 snímače krajní max,krajní low, dva prostřední -ty musí svítit = přes vetily dosáhnout polohy", "images": [], "videos": []}, {"id": "e849", "text": "4K0M - nejde kalibrace", "images": [], "videos": []}, {"id": "e850", "text": "braketa v levém horním rohu musí být zaslepená (jako na kalibračním kusu)", "images": [], "videos": []}]}, {"id": "c18", "name": "Nové modely - rozměr", "entries": [{"id": "e851", "text": "Heslo: 9", "images": [], "videos": []}, {"id": "e852", "text": "Nastavení analogových snímačů, pokud jsou křivá jádra", "images": [], "videos": []}, {"id": "e853", "text": "V nastavení kouknout jestli odpovídá model", "images": [], "videos": []}, {"id": "e854", "text": "V nastavení analogů kouknout který se hýbe - manuálně zahýbat (až do krajní pozice), sledovat na obrazovce kde se mění hodnoty", "images": [], "videos": []}, {"id": "e855", "text": "Vyresetovat v pracovní pozici (doraz o jádro), na displeji modrým tlačítkem", "images": ["Nové_modely_-_rozměr_68.jpg", "Nové_modely_-_rozměr_69.jpg"], "videos": []}, {"id": "e856", "text": "Pokud stále hlásí  Založte kus - zkontrolovat snímač v otvoru pro vkládání plugu, naproti je také v hlavě šroubu umístěna odrazka", "images": [], "videos": []}, {"id": "e857", "text": "Manuál H1BH - pokud pokračuje na displeji k dalšímu kroku  - píše vložte sáček, ale na displeji nesvítí potvrzení o vložení sáčku = snímač nebo odrazka v díře pro plug stále přiznává", "images": [], "videos": []}, {"id": "e858", "text": "Gascooler za He6", "images": [], "videos": []}, {"id": "e859", "text": "Nelze provést kalibraci - V5, V6 nejsou ve výchozí pozici", "images": [], "videos": []}, {"id": "e860", "text": "Klíček přepnout na 1, Heslo 1121", "images": [], "videos": []}, {"id": "e861", "text": "Kalibrace měřidla -> Vysunout pneuválce -> Zkalibrovat Aktuální hodnoty", "images": [], "videos": []}, {"id": "e862", "text": "Zkalibrováno musí být ve vysunuté pozice", "images": [], "videos": []}, {"id": "e863", "text": "Po kalibraci pneuválců pustí dál ke kalibraci přípravku", "images": [], "videos": []}]}, {"id": "c19", "name": "Měřák jigů", "entries": [{"id": "e864", "text": "Pokud nejde zkalibrovat", "images": [], "videos": []}, {"id": "e865", "text": "na klávesnici nastavit 32 a enter - kalibrace s pojezdem do výchozí polohy", "images": [], "videos": []}, {"id": "e866", "text": "pozor musí být zapnutý NumLock jinak nejdou číslice (nesvítí tam dioda)", "images": [], "videos": []}]}, {"id": "c20", "name": "Frézka", "entries": [{"id": "e867", "text": "zapnout el. Energii a hydrauliku", "images": [], "videos": []}, {"id": "e868", "text": "otáčky nastavení - musí zapadnout", "images": [], "videos": []}, {"id": "e869", "text": "přesné podložky pro vypodložení", "images": [], "videos": []}, {"id": "e870", "text": "fréza musí brát špony od materiálu, nesmí je tlačit pod něj", "images": [], "videos": []}, {"id": "e871", "text": "změna pohybů přes páku dole - osy X,Y,Z", "images": [], "videos": []}, {"id": "e872", "text": "ručně - zmáčknout pojistku, najet na materiál potom vypnout displej (vynuluje se) - o kolik uberu", "images": [], "videos": []}, {"id": "e873", "text": "manuální posuv na displeji - tlačítka dole", "images": [], "videos": []}, {"id": "e874", "text": "automatický posuv - nahoře, rychlost posuvu řídí potenciometr", "images": [], "videos": []}]}, {"id": "c21", "name": "Elektro", "entries": [{"id": "e875", "text": "Heslo: 1121", "images": [], "videos": []}, {"id": "e876", "text": "V rozvaděči žluté = ochranné (senzor, zámek), nejsou-li seplé nejde nic dalšího. Proklemovat", "images": [], "videos": []}, {"id": "e877", "text": "Frekvenční měnič - RESET -˃ START", "images": [], "videos": []}, {"id": "e878", "text": "ZÁLOŽNÍ ZDROJ", "images": [], "videos": []}, {"id": "e879", "text": "musí být přepnuto na MAN -˃ pak START-˃zapnout jistič", "images": [], "videos": []}, {"id": "e880", "text": "při vypínání naopak a čeká (chladí se, má doběh)", "images": [], "videos": []}, {"id": "e881", "text": "nafta aspoň 10%", "images": [], "videos": []}, {"id": "e882", "text": "zadní sklad- nahoře pohybová čidla - požár - vypnutí dole", "images": [], "videos": []}, {"id": "e883", "text": "tlačítka - kontola jestli se zmáčknout kontakty, numusí být vždy na středu", "images": [], "videos": []}, {"id": "e884", "text": "Zapínání ventilátorů na staré hale (první cesta, 3 místa) musí být vypínač vedle nich na Trvale (jde o výměnu vzduchu)", "images": [], "videos": []}, {"id": "e885", "text": "V kompresorovně na Trvale jde teplo na střechu, na Termostat jde do skladu, ale musí se nahodit jističe u sessleru nahoře", "images": [], "videos": []}, {"id": "e886", "text": "Hvězda a trojúhelník", "images": [], "videos": []}, {"id": "e887", "text": "tři propojení = trojúhelník (jen 230V), jedna propojka hvězda (400V)", "images": ["Elektro_70.jpg"], "videos": []}, {"id": "e888", "text": "Třífázový stykač - nemělo by být napětí mezí fází a zemí. Pokud jsem naměřil = zkrat vůči zemi -> kabel je porušený dotýká se vodivé části", "images": [], "videos": []}, {"id": "e889", "text": "Na tryskači přehodit směr otáčení v rozvaděči, tam kde jsou jen tři vodiče", "images": ["Elektro_71.jpg"], "videos": []}, {"id": "e890", "text": "Měřit mezi hnědým a modrým", "images": [], "videos": []}]}, {"id": "c22", "name": "Dusík stanice", "entries": [{"id": "e891", "text": "Pro odtlakování se otevírají dva kohouty co jsou za sebou", "images": [], "videos": []}, {"id": "e892", "text": "Ventil č. 20 a ten vedle. Už je předěláno", "images": [], "videos": []}, {"id": "e893", "text": "Pro zastavení tlakování 3 ventily vpředu - všechny zavřít", "images": [], "videos": []}, {"id": "e894", "text": "Pro zastavení do haly - za nádobami dva ventily, ten blíž k hale zavřít", "images": [], "videos": []}]}, {"id": "c23", "name": "Čerpačka", "entries": [{"id": "e895", "text": "Rozjezd po odstávce", "images": [], "videos": []}, {"id": "e896", "text": "do pecí + čerpačka", "images": [], "videos": []}, {"id": "e897", "text": "První tři čerpadla od dveří jsou k věžím (stačí když jde jedno), tři u nouzového východu jsou do výroby (pouští se dvě - axiální jako první)", "images": [], "videos": []}, {"id": "e898", "text": "1. Pustit aspoň vodu na heliu, aby byl odběr", "images": [], "videos": []}, {"id": "e899", "text": "- na pecích pustit zpětná čerpadla", "images": [], "videos": []}, {"id": "e900", "text": "- kontrola venku věží jestli jsou zaplé ventilátory", "images": [], "videos": []}, {"id": "e901", "text": "2. V čerpačce se pustí přívod změkčené vody, plovák by měl být dole = otevřený průtok do jímky. Při provozu se řídí hladinou vody, když je dost vysoko tak se zavře elektroventilem", "images": ["Čerpačka_72.jpg"], "videos": []}, {"id": "e902", "text": "3. První se pouští axiální  (to co stojí, zelené č.6) čerpadlo do výroby, nemělo by požadovaný odběr kdyby běželo čerpadlo vedle)", "images": [], "videos": []}, {"id": "e903", "text": "- napřed se zavodní, zároveň se povolí šroub ro odvzdušnění - když už teče voda, tak se zašroubuje  a zavře se voda pro zavodnění", "images": [], "videos": []}, {"id": "e904", "text": "- otevřít ventily (velké) pro přívod od čerpadla do výroby", "images": [], "videos": []}, {"id": "e905", "text": "- čerpadlo pustit na rozvaděči", "images": [], "videos": []}, {"id": "e906", "text": "= teď jde voda do výroby", "images": ["Čerpačka_73.jpg", "Čerpačka_74.jpg", "Čerpačka_75.jpg"], "videos": []}, {"id": "e907", "text": "4. Pustit čerpadlo k věžím, nemusí se odvzdušňovat, jen zavodnit a zase zavřit ventil", "images": [], "videos": []}, {"id": "e908", "text": "- pak otevřít ventil k věžím a pustit na rozvaděči + pustit věž (ventilátor), stará nebo nová podle do které jde (popsáno na trubkách)", "images": ["Čerpačka_76.jpg"], "videos": []}, {"id": "e909", "text": "5. Pustit druhé čerpadlo do výroby", "images": [], "videos": []}, {"id": "e910", "text": "- jen zavodnit a zavřít, otevřít ventil do výroby a pustit na rozvaděči", "images": [], "videos": []}, {"id": "e911", "text": "6. U pecí otevřít hlavní přívod změkčené vody, kohouty pro vypouštění musí být zavřené, kohouty pro napouštění vozíků - seřídit průtok", "images": [], "videos": []}, {"id": "e912", "text": "HAVARIJNÍ STAVY", "images": [], "videos": []}, {"id": "e913", "text": "Nízká hladina", "images": [], "videos": []}, {"id": "e914", "text": "- změkčená voda přívod - proklepnout plovák jestli není zaseklý ventil", "images": [], "videos": []}, {"id": "e915", "text": "- pokud neotevře elektroventil na potrubí, musí se otevřít bypas, ale podržet plovák dole aby nebylo potrubí pod tlakem", "images": [], "videos": []}, {"id": "e916", "text": "Vysoká hladina", "images": [], "videos": []}, {"id": "e917", "text": "- proklepnout plovák, zavřít přívod změkčené vody (měl by uzavřít elektroventil)", "images": [], "videos": []}, {"id": "e918", "text": "- pokud je problém a musí se odčerpat voda pryč =", "images": [], "videos": []}, {"id": "e919", "text": "Vyčerpání vody do kanálu", "images": [], "videos": []}, {"id": "e920", "text": "- zavodnit dvě prostřední čerpadla a uzavřít, otevřít ventily z jímky a otevřít ventily za čerpadly a ven v rohu místnosti Vypouštění chladící vody", "images": [], "videos": []}, {"id": "e921", "text": "- na rozvaděči pustit čerpadlo vypouštění", "images": [], "videos": []}, {"id": "e922", "text": "Delší výpadek", "images": [], "videos": []}, {"id": "e923", "text": "1. Zapne se záložní zdroj a vyjedou se pece", "images": [], "videos": []}, {"id": "e924", "text": "2. Na peci č.1 a č.2 se uzavře přívod změkčené chladící vody a natrhne se pitná voda (jen aby kapala)", "images": [], "videos": []}, {"id": "e925", "text": "3. V čerpačce se přepne také na záložní zdroj - Diesel, na peci č.3 se přepne na Diesel a pustí se zpětná čerpadla + v čerpačce zapnou normálně do výroby a ke věžím", "images": [], "videos": []}, {"id": "e926", "text": "Pec č.3 nemá přepad do kanálu", "images": ["Čerpačka_77.jpg", "Čerpačka_78.jpg", "Čerpačka_79.jpg"], "videos": []}, {"id": "e927", "text": "Při vysoké teplotě v čerpačce (byla 50°C) v zimě - pomohlo zastavení větráku na chladící věži a po 20min. opětovné zapnutí", "images": [], "videos": []}, {"id": "e928", "text": "Při mrazech zamrzly voštiny (otvory v kondenzátoru) a věž nechladila vodu", "images": [], "videos": []}, {"id": "e929", "text": "Pokud by nepomohlo - zkusit přidat čerpadlo 4 (zavodnit, otevřít dva ventily) a zapnout novou chladící věž", "images": [], "videos": []}, {"id": "e930", "text": "Normálně se větrák zapíná při teplotě v čerpačce 40°C (30°C normal)", "images": ["Čerpačka_80.jpg", "Čerpačka_81.jpg"], "videos": []}, {"id": "e931", "text": "JE JEDNO NA KTERÉM ROZVADĚČI SE PŘIDÁ ČERPADLO 4 - ALE MUSÍ SE  ZAPNOUT NOVÁ CHLADÍCÍ VĚŽ", "images": [], "videos": []}]}, {"id": "c24", "name": "Kotelna", "entries": [{"id": "e932", "text": "musí jít kompresory = vzduch, jinak nic nejede", "images": [], "videos": []}, {"id": "e933", "text": "senzory: na únik plynu (změřit na měřáku) - varuje i na  vrátnici= musí vyresetovat i tam, vody", "images": [], "videos": []}, {"id": "e934", "text": "Kotel", "images": [], "videos": []}, {"id": "e935", "text": "tlačítka:", "images": [], "videos": []}, {"id": "e936", "text": "24 hod kontrola - jen natáhne hodiny", "images": [], "videos": []}, {"id": "e937", "text": "Předvolba napáječky - 1/0/2 z jakého jede čerpadla", "images": [], "videos": []}, {"id": "e938", "text": "Řízení hořáku - pro znovuzapnutí hořáku na ODBLOKOVAT→PROVOZ→počkat na měřáku na napuštění vody - nad rysku→", "images": [], "videos": []}, {"id": "e939", "text": "→přepnout na STUPEŇ 2 (pokud je na manometru 5bar)→na rozvaděči - na displeji mačkat ACK pak KVIT - dokud chyby nezmizí", "images": [], "videos": []}, {"id": "e940", "text": "na 15 min můžu přepnout na II. stupeň a pak zpět aby hořák šel na vyšší vykon, pak můžu opět opakovat (na vyšší a zpět)", "images": [], "videos": []}, {"id": "e941", "text": "DEMI voda výroba", "images": [], "videos": []}, {"id": "e942", "text": "hlavní přívod vody otevřít", "images": [], "videos": []}, {"id": "e943", "text": "do manuálu HAND→modré tlačítko→na rozvaděči: panel DEMIvoda (K8) -Osmóza→Provoz→do 90%→Standby (zelené tl.)→na rozvaděči: panel DEMIvoda (K8) - Blokace", "images": [], "videos": []}, {"id": "e944", "text": "hlavní přívod vody uzavřít", "images": [], "videos": []}, {"id": "e945", "text": "za provozu: do ručně pak modrý, počkat aby se udělala voda pak stand by počkat než se rozsvítí a můžu ukončit zavřením vody a blokace na displeji", "images": [], "videos": []}, {"id": "e946", "text": "Při nájezdu", "images": [], "videos": []}, {"id": "e947", "text": "pustit vodu = hlavní přívod vody otevřít + do Auto + na rozvaděči: panel DEMIvoda (K8) -Osmóza→Provoz", "images": ["Kotelna_82.jpg"], "videos": []}, {"id": "e948", "text": "Při zapínání demi vody po víkendu - chyba pmin - zkusit reset chyby (červené tlačítko na panelu demi vody)", "images": [], "videos": []}, {"id": "e949", "text": "pokud nejde - demi voda v ručním režimu, otevřený hlavní ventil surové vody, příkaz na demi Provoz", "images": [], "videos": []}, {"id": "e950", "text": "otevřít mechanicky ventil pod panelem a čekat až zmizí chyba", "images": [], "videos": []}, {"id": "e951", "text": "Topení", "images": [], "videos": []}, {"id": "e952", "text": "- u helia 4 nahoře - otevřít plyn, zapnout a přepnout na topení", "images": [], "videos": []}, {"id": "e953", "text": "- v kotelně zapnout 2x čerpadla (kancelář, šatny)", "images": [], "videos": []}, {"id": "e954", "text": "- na displeji musí být u pozic Kancelář, Hala A, Hala B nastaveno na Topení", "images": [], "videos": []}, {"id": "e955", "text": "- při zapínání dát termostat na víc aby se zjistilo jestli vůbec topí", "images": [], "videos": []}, {"id": "e956", "text": "- na displeji v kotelně se ovládá stará část kanceláře (po skleník), v kanceláři už jen termostat", "images": [], "videos": []}, {"id": "e957", "text": "- nová část se ovládá přímo v kanceláři - kartový systém - potvrzuje se horním tlačítkem, pokud je v manuálu topí nepřetržitě, automat se může se zapnout když má natopeno (je to rychlejší)", "images": [], "videos": []}, {"id": "e958", "text": "Kotelna displej", "images": [], "videos": []}, {"id": "e959", "text": "DIR - hlavní přehled", "images": [], "videos": []}, {"id": "e960", "text": "šipky pohyb", "images": [], "videos": []}, {"id": "e961", "text": "shift - změna", "images": [], "videos": []}, {"id": "e962", "text": "potvrzení enter", "images": [], "videos": []}, {"id": "e963", "text": "Topné jednotky", "images": [], "videos": []}, {"id": "e964", "text": "otevřít plyn, zapnout na ohřev", "images": [], "videos": []}, {"id": "e965", "text": "v rozvaděči:", "images": [], "videos": []}, {"id": "e966", "text": "ohřev na chod", "images": [], "videos": []}, {"id": "e967", "text": "vzt na provoz", "images": [], "videos": []}, {"id": "e968", "text": "ventilátor do ručně (musí běžet)", "images": [], "videos": []}, {"id": "e969", "text": "jednotka výstupní sklad k legu - šedé krabičky = termostaty u hořáku - reset chyby ze spodu je tlačítko", "images": [], "videos": []}, {"id": "e970", "text": "do skladu otevřená klapka nim na 60, u 40 se přehřívá potrubí", "images": [], "videos": []}, {"id": "e971", "text": "Topení Jídelna", "images": [], "videos": []}, {"id": "e972", "text": "když netopilo, zapnutí ventilátoru přes stykač natvrdo", "images": ["Kotelna_83.jpg"], "videos": []}, {"id": "e973", "text": "Poloha klapek Sací by měla být na 20%, je nula takže asi zamrznuto", "images": [], "videos": []}, {"id": "e974", "text": "Lze zapnout ventilátor natvrdo, ale jen když běží oběhové čerpadlo ústředního topení - KONTROLA jestli je sepnuté", "images": ["Kotelna_84.jpg", "Kotelna_85.jpg"], "videos": []}, {"id": "e975", "text": "Kotelna", "images": [], "videos": []}, {"id": "e976", "text": "Chyby na panelu kotle -zkusit vymazat na panelu - SIGNAL,ZRUSIT a na displeji ACK, pokud nelze (je porucha hořáku) ->  vypnout hořák až na pozici odblokovat ->  vymazat chyby na displeji ACK -> zapnout hořák na I. Stupeň  -> počkat na min. 4bar na manometru  -> může se zapnout na II. Stupeň", "images": [], "videos": []}, {"id": "e977", "text": "Chyby většinou NEJNIŽŠÍ STAV VODY - kontrola vodoznaku - dopouští kotelník, PORUCHA HOŘÁKU - vypnout hořák a znovu zapnout (postup výše)", "images": [], "videos": []}, {"id": "e978", "text": "Někdy je potřeba natáhnout 24 HOD. KONTROLU", "images": ["Kotelna_86.jpg", "Kotelna_87.jpg", "Kotelna_88.jpg", "Kotelna_89.jpg", "Kotelna_90.jpg"], "videos": []}, {"id": "e979", "text": "Zapnutí topení šatny", "images": [], "videos": []}, {"id": "e980", "text": "Na panelu navolit Požadavek na UT", "images": [], "videos": []}, {"id": "e981", "text": "Čerpadlo M5 na Provoz a Servisní chod na Provoz", "images": [], "videos": []}]}, {"id": "c25", "name": "Kompresorovna", "entries": [{"id": "e982", "text": "Zimní/letní režim", "images": [], "videos": []}, {"id": "e983", "text": "klapky nad kompresory přepnout - po žebříku nahoru", "images": [], "videos": []}, {"id": "e984", "text": "zimní - klapky zavřít, topíme dovnitř + u sessleru nad chemickou sprchou - otevřít klapky do skladu", "images": [], "videos": []}, {"id": "e985", "text": "kompresorovna vypnout z termostat na vypnuto", "images": [], "videos": []}]}, {"id": "c26", "name": "Rozvodna", "entries": [{"id": "e986", "text": "PEC 3 - vypnout oba jističe Přívod č.1 a Přívod č. 2 + kompenzaci na dveřích rozvaděče = VYPÍNAČ REGULÁTORU na OFF", "images": [], "videos": []}, {"id": "e987", "text": "Při zapínání - pustit kompenzaci", "images": [], "videos": []}, {"id": "e988", "text": "Ve stejném rozvaděči i jističe a trafo pro Nový kanalis (od průchodu k Přítočnu)", "images": [], "videos": []}, {"id": "e989", "text": "Pokud odejde (shoří) trafo lze propojit z jednoho do druhého, ale není dimenzováno aby utáhlo vše", "images": [], "videos": []}, {"id": "e990", "text": "POZOR nepustit trafa do sebe, před zapnutí propojky je NUTNÉ VYPNOUT trafo které nechceme používat", "images": ["Rozvodna_91.jpg", "Rozvodna_92.jpg", "Rozvodna_93.jpg", "Rozvodna_94.jpg"], "videos": []}, {"id": "e991", "text": "Vypnutí pecí č.1 a č.2 + shodit i jističe uprostřed pro Regulátory na 1 i 2", "images": [], "videos": []}, {"id": "e992", "text": "Při zapínání - pustit kompenzaci", "images": [], "videos": []}, {"id": "e993", "text": "Ve stejném rozvaděči i jističe a trafo pro Nový kanalis (od průchodu k Přítočnu)", "images": [], "videos": []}, {"id": "e994", "text": "Pokud odejde (shoří) trafo lze propojit z jednoho do druhého, ale není dimenzováno aby utáhlo vše", "images": [], "videos": []}, {"id": "e995", "text": "POZOR nepustit trafa do sebe, před zapnutí propojky je NUTNÉ VYPNOUT trafo které nechceme používat", "images": ["Rozvodna_95.jpg", "Rozvodna_96.jpg", "Rozvodna_97.jpg", "Rozvodna_98.jpg"], "videos": []}, {"id": "e996", "text": "Zapnutí TRAFA", "images": [], "videos": []}, {"id": "e997", "text": "Vlevo za dveřmi při vstupu RSP - Světla ČOV, sklad vrata atd.", "images": ["Rozvodna_99.jpg", "Rozvodna_100.jpg", "Rozvodna_101.jpg"], "videos": []}]}, {"id": "c27", "name": "EPS", "entries": [{"id": "e998", "text": "Při výpadku EPS nahodit EPS a jistič vedle pro plyn FHUP", "images": [], "videos": []}]}, {"id": "c28", "name": "Různé", "entries": [{"id": "e999", "text": "Při závitování do duralu - mazat lihem jinak se závitník zataví", "images": [], "videos": []}, {"id": "e1000", "text": "Vrtáky pro závity - závit × 0,8 př. M5 × 0,8 = 4 mm vrták", "images": [], "videos": []}, {"id": "e1001", "text": "Jigy - mechanicky podotahovat, vyměnit o-kroužky, silon, závit do jigu G ⅛", "images": [], "videos": []}, {"id": "e1002", "text": "závit do rychlospojky - ¼", "images": [], "videos": []}, {"id": "e1003", "text": "Kompresorovna - kontrola oleje, odkalit aspoň 1x týdně", "images": [], "videos": []}, {"id": "e1004", "text": "teplota, tlak, rozdíl motohodiny", "images": [], "videos": []}, {"id": "e1005", "text": "zapsat údaje, na č.1 - cílový tlak: v parametry", "images": [], "videos": []}, {"id": "e1006", "text": "vysokotlak - motohodiny, teplota, tlak", "images": [], "videos": []}, {"id": "e1007", "text": "puštění vysokotlaku - na vzdušníku (velká modrá nádoba) musí být 5 bar = napřed pustit nízkotlak", "images": [], "videos": []}, {"id": "e1008", "text": "vysokotlak - střídání po měsíci, po měsíci dolít olej", "images": [], "videos": []}, {"id": "e1009", "text": "napřed pustit druhý vysokotlak až potom vypnout první", "images": [], "videos": []}, {"id": "e1010", "text": "na 5 - odkalit malou nádobku - celou vypustit", "images": [], "videos": []}, {"id": "e1011", "text": "dolít olej do nádržky", "images": [], "videos": []}, {"id": "e1012", "text": "HESLA", "images": [], "videos": []}, {"id": "e1013", "text": "kód sklady 1321", "images": [], "videos": []}, {"id": "e1014", "text": "ADAX všechny přípravky a headerfluxer 2279", "images": ["Různé_102.jpg"], "videos": []}, {"id": "e1015", "text": "Corefin6 - pro odklon Finů - 1620", "images": [], "videos": []}, {"id": "e1016", "text": "Fin 4 - namotání  na válce 16204", "images": [], "videos": []}, {"id": "e1017", "text": "Fin 5 - namítání na válce 16205", "images": ["Různé_103.jpg"], "videos": []}, {"id": "e1018", "text": "Měřák odporu topení - spojit všechny 4 plochy krokodýlů a Zero = vynulovat. Nastavit na ohmy, tečku na 4 desetinné místo (pomocí šipek nahoru). Poté lze měřit pomocí Measure OK, nekonečno je ideální stav. Topení kolem 0,5 Ohmu", "images": [], "videos": []}]}];
